This example implements a simple MVVM (Model-View-ViewModel) architecture with data persistence using `@AppStorage` (for simplicity) and a basic habit list.

### 1. The Model (`Habit.swift`)
This defines what a "Habit" is.

```swift
import Foundation

struct Habit: Identifiable, Codable {
    var id = UUID()
    var name: String
    var isCompleted: Bool = false
}
```

### 2. The ViewModel (`HabitViewModel.swift`)
This handles the logic, saving, and loading of habits.

```swift
import SwiftUI

class HabitViewModel: ObservableObject {
    @AppStorage("habits") var habitsData: Data = Data()
    @Published var habits: [Habit] = [] {
        didSet {
            if let encoded = try? JSONEncoder().encode(habits) {
                habitsData = encoded
            }
        }
    }

    init() {
        if let decoded = try? JSONDecoder().decode([Habit].self, from: habitsData) {
            habits = decoded
        }
    }

    func addHabit(name: String) {
        let newHabit = Habit(name: name)
        habits.append(newHabit)
    }

    func toggleHabit(at index: Int) {
        habits[index].isCompleted.toggle()
    }
}
```

### 3. The Main View (`ContentView.swift`)
This builds the UI.

```swift
import SwiftUI

