                            Image(systemName: viewModel.habits[index].isCompleted ? "checkmark.circle.fill" : "circle")
                                .foregroundColor(viewModel.habits[index].isCompleted ? .green : .gray)
                                .onTapGesture {
                                    viewModel.toggleHabit(at: index)
                                }
                        }
                    }
                }
            }
            .navigationTitle("Habit Tracker")
