### The Code (`ContentView.swift`)

Replace the contents of your `ContentView.swift` with the following:

```swift
import SwiftUI

struct Habit: Identifiable, Codable {
    var id = UUID()
    var name: String
    var isCompleted: Bool = false
}

struct ContentView: View {
    @State private var habits: [Habit] = []
    @State private var newHabitName = ""

    // Save/Load using UserDefaults
    @AppStorage("saved_habits") var savedHabitsData: Data = Data()

    var body: some View {
        NavigationView {
            VStack {
                HStack {
                    TextField("New habit...", text: $newHabitName)
                        .textFieldStyle(RoundedBorderTextFieldStyle())
                    Button("Add") {
                        guard !newHabitName.isEmpty else { return }
                        habits.append(Habit(name: newHabitName))
                        newHabitName = ""
                        save()
                    }
                }
                .padding()

                List {
                    ForEach($habits) { $habit in
                        HStack {
                            Text(habit.name)
                            Spacer()
                            Image(systemName: habit.isCompleted ? "checkmark.circle.fill" : "circle")
                                .foregroundColor(habit.isCompleted ? .green : .gray)
                                .onTapGesture {
                                    habit.isCompleted.toggle()
                                    save()
                                }
                        }
                    }
                    .onDelete(perform: deleteHabits)
                }
            }
            .navigationTitle("Habit Tracker")
            .onAppear(perform: load)
        }
    }

    func save() {
        if let encoded = try? JSONEncoder().encode(habits) {
            savedHabitsData = encoded
        }
    }

    func load() {
        if let decoded = try? JSONDecoder().decode([Habit].self, from: savedHabitsData) {
            habits = decoded
        }
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        save()
    }
}
```

### Key Technical Concepts Used:

1.  **`@State`**: This property wrapper monitors the `habits` array. Whenever the array changes, SwiftUI automatically re-renders the UI to reflect those changes.
2.  **`@AppStorage`**: This acts as a persistent wrapper for `UserDefaults`. It ensures that your habits remain saved even after you close and reopen the app.
3.  **`Identifiable` Protocol**: Allows the `List` view to efficiently track which habit is which using a `UUID`.
4.  **`Codable`**: This allows us to convert the `Habit` struct into JSON data so it can be saved to the phone's disk.
5.  **`onDelete`**: A native SwiftUI modifier that enables the standard "swipe-to-delete" functionality common in iOS apps.

### How to expand this:
*   **Persistent Database**: Replace `UserDefaults` with **SwiftData** (Apple’s modern framework for persistent storage).
*   **Daily Reset**: Use a `Date` property in your `Habit` struct to check if the last completion was today, and reset the `isCompleted` status automatically at midnight.
*   **Notifications**: Use the `UserNotifications` framework to remind the user to check off their habits at a specific time.

