    @State private var habits: [Habit] = []
    @State private var newHabitName = ""

    var body: some View {
        NavigationView {
            VStack {
                // Input Area
                HStack {
                    TextField("New habit...", text: $newHabitName)
                        .textFieldStyle(RoundedBorderTextFieldStyle())
                    Button("Add") {
                        addHabit()
                    }
                    .disabled(newHabitName.isEmpty)
                }
                .padding()

                // List Area
                List {
                    ForEach($habits) { $habit in
                        HStack {
                            Text(habit.name)
                            Spacer()
                            Image(systemName: habit.isCompleted ? "checkmark.circle.fill" : "circle")
                                .foregroundColor(habit.isCompleted ? .green : .gray)
                                .onTapGesture { habit.isCompleted.toggle(); save() }
                        }
                    }
                    .onDelete(perform: deleteHabit)
                }
            }
            .navigationTitle("Habit Tracker")
            .onAppear(perform: loadHabits)
        }
    }

    // Logic
    func addHabit() {
        habits.append(Habit(name: newHabitName))
        newHabitName = ""
        save()
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        save()
    }

    func save() {
        if let encoded = try? JSONEncoder().encode(habits) {
            habitsData = encoded
        }
    }

    func loadHabits() {
        if let decoded = try? JSONDecoder().decode([Habit].self, from: habitsData) {
            habits = decoded
        }
    }
}
```

### Key Components Explained:

1.  **`@AppStorage`**: This is a property wrapper that automatically persists your data to `UserDefaults`. It is the simplest way to save local state in a small app without setting up CoreData or SwiftData.
2.  **`JSONEncoder/Decoder`**: Since `@AppStorage` works best with primitives (strings/ints), we convert our `[Habit]` array into `Data` (binary format) to store it.
3.  **`List` + `ForEach`**: This creates the native iOS table view. Passing `$habits` (with a binding) allows the toggle button to update the state directly within the array.
4.  **`onDelete`**: This automatically adds the native "swipe-to-delete" functionality that users expect on iOS.

