#### `db.js` (The Sync Service)
This file handles creating the local database and setting up the "continuous" sync.

```javascript
import PouchDB from 'pouchdb';

// 1. Initialize local DB
export const localDB = new PouchDB('survey_data', { adapter: 'indexeddb' });

// 2. Define Remote DB (Your CouchDB instance)
const remoteDB = new PouchDB('http://admin:password@localhost:5984/surveys');

// 3. Set up Bi-directional Sync
export const syncDB = () => {
  localDB.sync(remoteDB, {
    live: true, // Keep it running in the background
    retry: true // Automatically reconnect if network drops
  })
  .on('change', (info) => console.log('Synced:', info))
  .on('error', (err) => console.log('Sync Error:', err));
};
```

