### 3. The Sync Engine
This hook listens for network changes and automatically pushes pending items to the server.

```javascript
// useSync.js
import { useEffect } from 'react';
import { db } from './db';

export const useSync = () => {
  useEffect(() => {
    const handleSync = async () => {
      if (!navigator.onLine) return;

      // Find all unsynced records
      const unsynced = await db.surveys.where('synced').equals(0).toArray();

      for (const item of unsynced) {
        try {
          const response = await fetch('/api/surveys', {
            method: 'POST',
            body: JSON.stringify(item)
          });

          if (response.ok) {
            await db.surveys.update(item.id, { synced: 1 });
          }
        } catch (err) {
          console.error("Sync failed for", item.id, err);
        }
      }
    };

    window.addEventListener('online', handleSync);
    handleSync(); // Run on mount too

    return () => window.removeEventListener('online', handleSync);
  }, []);
};
```

---

### 4. Saving Data (The Survey Component)
When the user clicks "Submit," you save to IndexedDB, not the API.

