### 2. The Hook: Offline-First Logic
This hook manages saving to the local DB and triggers a sync whenever the network is detected.

```javascript
// useSurveySync.js
import { useEffect } from 'react';
import { db } from './db';

export const useSurveySync = () => {
  const syncData = async () => {
    const pending = await db.surveys.where('status').equals('pending').toArray();

    for (const item of pending) {
      try {
        await fetch('/api/surveys', {
          method: 'POST',
          body: JSON.stringify(item.data)
        });
        await db.surveys.update(item.id, { status: 'synced' });
      } catch (err) {
        console.error("Sync failed for item", item.id);
      }
    }
  };

  useEffect(() => {
    window.addEventListener('online', syncData);
    return () => window.removeEventListener('online', syncData);
  }, []);

  const saveSurvey = async (data) => {
    const isOnline = navigator.onLine;
    await db.surveys.add({
      data,
      status: isOnline ? 'synced' : 'pending',
      timestamp: Date.now()
    });

    if (isOnline) syncData();
  };

  return { saveSurvey };
};
```

