### 2. Setup the Local Database
First, install dependencies: `npx expo install expo-sqlite @react-native-community/netinfo`.

```javascript
// database.js
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabaseSync('survey.db');

export const initDb = () => {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id INTEGER PRIMARY KEY NOT NULL,
      data TEXT,
      is_synced INTEGER DEFAULT 0
    );
  `);
};

export const saveSurveyLocal = (data) => {
  db.runSync('INSERT INTO surveys (data, is_synced) VALUES (?, 0)', [JSON.stringify(data)]);
};

export const getUnsyncedSurveys = () => {
  return db.getAllSync('SELECT * FROM surveys WHERE is_synced = 0');
};

export const markAsSynced = (id) => {
  db.runSync('UPDATE surveys SET is_synced = 1 WHERE id = ?', [id]);
};
```

