### 3. Synchronization Engine
This function attempts to push data to your backend API.

```javascript
// syncService.js
import { getUnsyncedSurveys, markAsSynced } from './database';

export const syncData = async () => {
  const unsynced = getUnsyncedSurveys();

  for (const item of unsynced) {
    try {
      const response = await fetch('https://your-api.com/surveys', {
        method: 'POST',
        body: item.data,
      });

      if (response.ok) {
        markAsSynced(item.id);
      }
    } catch (error) {
      console.error("Sync failed for item", item.id);
      break; // Stop if network fails mid-sync
    }
  }
};
```

