### 4. Hooking into Network State
Use `@react-native-community/netinfo` to listen for connectivity changes.

```javascript
// App.js
import { useEffect } from 'react';
import NetInfo from '@react-native-community/netinfo';
import { initDb, saveSurveyLocal } from './database';
import { syncData } from './syncService';

export default function App() {
  useEffect(() => {
    initDb();

    // Listen for network changes
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected) {
        console.log("Back online! Syncing...");
        syncData();
      }
    });

    return () => unsubscribe();
  }, []);

  const handleSave = (formData) => {
    saveSurveyLocal(formData);
    // Attempt sync immediately if online
    NetInfo.fetch().then(state => {
      if (state.isConnected) syncData();
    });
  };

  return (/* Your Survey UI */);
}
```

