### 3. Synchronization Logic

The sync function is the core of the app. It compares the `last_pulled_at` timestamp to fetch only new updates.

```javascript
// sync.js
import { synchronize } from '@nozbe/watermelondb/sync'
import database from './database'

export async function syncDatabase() {
  await synchronize({
    database,
    pullChanges: async ({ lastPulledAt }) => {
      const response = await fetch(`https://api.myapp.com/sync?last_pulled_at=${lastPulledAt}`)
      return await response.json() // returns { changes, timestamp }
    },
    pushChanges: async ({ changes }) => {
      await fetch('https://api.myapp.com/sync', {
        method: 'POST',
        body: JSON.stringify(changes),
      })
    },
  })
}
```

