import { useEffect } from 'react';
import { db } from './db';

export function useSync() {
  const syncData = async () => {
    const pendingItems = await db.surveys.where('status').equals('pending').toArray();

    for (const item of pendingItems) {
      try {
        const response = await fetch('/api/surveys', {
          method: 'POST',
          body: JSON.stringify(item)
        });

        if (response.ok) {
          // Mark as synced or delete from local DB
          await db.surveys.update(item.id, { status: 'synced' });
          console.log(`Synced item ${item.id}`);
        }
      } catch (err) {
        console.error("Still offline, keeping item in queue");
      }
    }
  };

  useEffect(() => {
    window.addEventListener('online', syncData);
    // Initial check on load
    syncData();

    return () => window.removeEventListener('online', syncData);
  }, []);
}
