### 4. The Sync Logic
This function attempts to push data to your API. If successful, it marks the local record as `synced`.

```javascript
async function syncData() {
  if (!navigator.onLine) return;

  const pendingSurveys = await db.surveys.where('status').equals('pending').toArray();

  for (const survey of pendingSurveys) {
    try {
      const response = await fetch('/api/surveys', {
        method: 'POST',
        body: JSON.stringify(survey),
        headers: { 'Content-Type': 'application/json' }
      });

      if (response.ok) {
        // Mark as synced or remove from local DB
        await db.surveys.update(survey.id, { status: 'synced' });
      }
    } catch (err) {
      console.error("Sync failed for record", survey.id);
    }
  }
}
```

### 5. Auto-Sync Trigger
Listen for connectivity changes to trigger the sync automatically.

```javascript
window.addEventListener('online', () => {
  console.log("Back online! Syncing...");
  syncData();
});
```

