### 2. The Setup

First, install the dependencies:
```bash
npm install rxdb rxjs pouchdb-adapter-idb pouchdb-adapter-http
```

### 3. Database Initialization (`db.js`)
This creates a local database that persists in the browser’s `IndexedDB`.

```javascript
import { createRxDatabase, addRxPlugin } from 'rxdb';
import { getRxStoragePouch, addPouchPlugin } from 'rxdb/plugins/pouchdb';
import pouchdbAdapterIdb from 'pouchdb-adapter-idb';

addPouchPlugin(pouchdbAdapterIdb);

export const initDB = async () => {
  const db = await createRxDatabase({
    name: 'survey_db',
    storage: getRxStoragePouch('idb')
  });

  // Define the Survey schema
  await db.addCollections({
    surveys: {
      schema: {
        version: 0,
        primaryKey: 'id',
        type: 'object',
        properties: {
          id: { type: 'string' },
          location: { type: 'string' },
          notes: { type: 'string' },
          synced: { type: 'boolean' }
        }
      }
    }
  });

  return db;
};
```

### 4. Setting up Synchronization (`sync.js`)
This handles the logic of pushing local changes to your CouchDB server whenever the app comes back online.

```javascript
export const startSync = (db) => {
  const syncURL = 'https://your-couchdb-server.com/surveys/';

  const replicationState = db.surveys.syncCouchDB({
    remote: syncURL,
    direction: {
      pull: true,
      push: true
    },
    options: { live: true, retry: true }
  });

  return replicationState;
};
```

### 5. Using it in a React Component
This component saves data locally immediately. If the user is offline, it stays in IndexedDB. When online, the sync engine fires.

```jsx
import React, { useEffect, useState } from 'react';
import { initDB } from './db';
import { startSync } from './sync';

function SurveyForm() {
  const [db, setDb] = useState(null);

  useEffect(() => {
    initDB().then(database => {
      setDb(database);
      startSync(database); // Start syncing automatically
    });
  }, []);

  const saveSurvey = async (data) => {
    await db.surveys.insert({
      id: new Date().getTime().toString(),
      ...data,
      synced: false
    });
    alert("Saved locally! Will sync when online.");
  };

  return (
    <button onClick={() => saveSurvey({ location: 'Plot A', notes: 'Clear' })}>
      Submit Survey
    </button>
  );
}
```

