// services/syncService.js
import NetInfo from "@react-native-community/netinfo";
import { database } from '../database';

export const syncData = async () => {
  const isConnected = (await NetInfo.fetch()).isConnected;
  if (!isConnected) return;

  const pendingSurveys = await database.get('surveys')
    .query(Q.where('sync_status', 'created'))
    .fetch();

  for (const survey of pendingSurveys) {
    try {
      const response = await api.post('/surveys', survey);
      if (response.status === 200) {
        await database.write(async () => {
          await survey.update(s => s.syncStatus = 'synced');
        });
      }
    } catch (e) {
      console.error("Sync failed for item", survey.id);
    }
  }
};
```

