### 3. The Sync Manager
This script handles the logic of pushing local changes to your server and pulling updates.

```javascript
import { synchronize } from '@nozbe/watermelondb/sync'

async function syncSurveys(database) {
  await synchronize({
    database,
    pullChanges: async ({ lastPulledAt }) => {
      const response = await fetch(`https://api.yoursite.com/sync?last_pulled=${lastPulledAt}`)
      return await response.json() // Expects { changes, timestamp }
    },
    pushChanges: async ({ changes, lastPulledAt }) => {
      await fetch(`https://api.yoursite.com/sync`, {
        method: 'POST',
        body: JSON.stringify({ changes }),
      })
    },
  })
}
```

