#### A. Saving Locally
When the user clicks "Submit," we save to the local SQLite database regardless of connection status.

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

const saveSurveyLocally = (data) => {
  db.transaction(tx => {
    tx.executeSql(
      'INSERT INTO surveys (site_name, lat, lng, notes, synced) VALUES (?, ?, ?, ?, 0)',
      [data.name, data.lat, data.lng, data.notes],
      (_, result) => console.log("Saved locally!"),
      (_, error) => console.error(error)
    );
  });
};
```

#### B. The Sync Engine
This function runs periodically or when the app detects an internet connection.

```javascript
import NetInfo from "@react-native-community/netinfo";

const syncData = async () => {
  const isConnected = (await NetInfo.fetch()).isConnected;
  if (!isConnected) return;

  // 1. Fetch unsynced records
  db.transaction(tx => {
    tx.executeSql('SELECT * FROM surveys WHERE synced = 0', [], (_, { rows }) => {
      const unsynced = rows._array;

      unsynced.forEach(async (record) => {
        // 2. Push to API
        try {
          const response = await fetch('https://api.yourdomain.com/surveys', {
            method: 'POST',
            body: JSON.stringify(record)
          });

          if (response.ok) {
            // 3. Mark as synced
            db.executeSql('UPDATE surveys SET synced = 1 WHERE id = ?', [record.id]);
          }
        } catch (e) {
          console.log("Sync failed, will retry later.");
        }
      });
    });
  });
};
```

