### 2. Implementation Steps

#### A. Define the Schema (`schema.js`)
Define your survey data structure.
```javascript
import { appSchema, tableSchema } from '@nozbe/watermelondb'

export default appSchema({
  version: 1,
  tables: [
    tableSchema({
      name: 'surveys',
      columns: [
        { name: 'surveyor_name', type: 'string' },
        { name: 'coordinates', type: 'string' },
        { name: 'notes', type: 'string' },
        { name: 'synced', type: 'boolean' },
      ],
    }),
  ],
})
```

#### B. The Sync Logic (`sync.js`)
This is where the magic happens. You implement a pull-and-push mechanism.

```javascript
import { synchronize } from '@nozbe/watermelondb/sync'

async function syncSurveys(database) {
  await synchronize({
    database,
    pullChanges: async ({ lastPulledAt }) => {
      const response = await fetch(`https://api.myapp.com/sync?since=${lastPulledAt}`)
      return await response.json() // { changes: {...}, timestamp: ... }
    },
    pushChanges: async ({ changes, lastPulledAt }) => {
      await fetch(`https://api.myapp.com/sync`, {
        method: 'POST',
        body: JSON.stringify({ changes }),
      })
    },
  })
}
```

#### C. Handling Connectivity (`App.js`)
Use `@react-native-community/netinfo` to trigger syncs when the user goes from "offline" to "online."

```javascript
import NetInfo from "@react-native-community/netinfo";

useEffect(() => {
  const unsubscribe = NetInfo.addEventListener(state => {
    if (state.isConnected) {
      console.log("Back online! Syncing...");
      syncSurveys(database);
    }
  });
  return () => unsubscribe();
}, []);
```

