### 2. Implementation: The Sync Logic (Conceptual)

We will use a custom hook to manage the state and connectivity.

```javascript
import { useNetInfo } from "@react-native-community/netinfo";
import { useEffect } from "react";
import { database } from "./db"; // Your local DB instance

export const useSync = () => {
  const netInfo = useNetInfo();

  const syncData = async () => {
    // 1. Fetch all 'pending' records from local SQLite
    const pendingRecords = await database.get('surveys').query(Q.where('status', 'pending')).fetch();

    for (const record of pendingRecords) {
      try {
        await api.post('/surveys', record);
        // 2. Mark as synced locally
        await record.update(r => r.status = 'synced');
      } catch (e) {
        console.error("Sync failed for record", record.id);
      }
    }
  };

  useEffect(() => {
    if (netInfo.isConnected) {
      syncData();
    }
  }, [netInfo.isConnected]);
};
```

