### 2. The Implementation (HTML + JS)

```html
<!DOCTYPE html>
<html>
<body>
  <h3>Offline Field Surveyor</h3>
  <input id="data" placeholder="Survey Note...">
  <button onclick="saveData()">Save</button>
  <p id="status"></p>

  <script src="https://unpkg.com/idb@7/build/umd.js"></script>
  <script>
    const dbPromise = idb.openDB('survey-db', 1, { upgrade(db) { db.createObjectStore('queue', { autoIncrement: true }); }});

    // Save locally
    async function saveData() {
      const val = document.getElementById('data').value;
      await (await dbPromise).add('queue', { val, ts: Date.now() });
      document.getElementById('data').value = '';
      syncData(); // Attempt sync
    }

    // Sync to Server
    async function syncData() {
      if (!navigator.onLine) return;
      const db = await dbPromise;
      let tx = db.transaction('queue', 'readwrite');
      let store = tx.store;
      let entries = await store.getAll();

      for (const entry of entries) {
        try {
          // Replace with your actual API endpoint
          await fetch('/api/submit', { method: 'POST', body: JSON.stringify(entry) });
          await store.delete(entry.id); // Remove from queue on success
        } catch (e) { console.error("Sync failed", e); break; }
      }
    }

    window.addEventListener('online', syncData);
    document.getElementById('status').innerText = navigator.onLine ? "Online" : "Offline";
    window.addEventListener('offline', () => document.getElementById('status').innerText = "Offline");
  </script>
</body>
</html>
```

