  return db.add('surveys', { ...data, synced: false, timestamp: Date.now() });
};
```

#### B. The Sync Engine (`sync.js`)
This function attempts to upload data whenever the connection is restored.

```javascript
export const syncData = async () => {
  if (!navigator.onLine) return;

  const db = await openDB('SurveyDB', 1);
  const tx = db.transaction('surveys', 'readwrite');
  const store = tx.objectStore('surveys');
  const all = await store.getAll();

  for (const record of all) {
    if (!record.synced) {
      try {
        await fetch('/api/surveys', {
          method: 'POST',
          body: JSON.stringify(record)
        });
        // Mark as synced locally
        await store.put({ ...record, synced: true });
      } catch (e) {
        console.error("Sync failed, will retry later.");
      }
    }
  }
};
```

#### C. The UI Component (`App.js`)
This connects the form to the offline logic.

