    e.preventDefault();
    const data = { notes: e.target.notes.value };

    await saveSurvey(data);
    alert('Saved locally!');

    // Attempt sync immediately if online
    syncData();
  };

  return (
    <form onSubmit={handleSubmit}>
      <input name="notes" placeholder="Survey Notes" required />
      <button type="submit">Submit</button>
    </form>
  );
}
```

