You need a WebSocket connection to push messages instantly without the client needing to refresh.

```javascript
// server.js
const io = require("socket.io")(3000);

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  // Join a specific room based on conversation ID
  socket.on("join_room", (room) => socket.join(room));

  // Handle sending a message
  socket.on("send_message", (data) => {
    // data = { room: '123', sender: 'userA', message: 'Hello!' }
    socket.to(data.room).emit("receive_message", data);

    // Save to database here (e.g., MongoDB)
    saveMessageToDB(data);
  });
});
```

