### 3. Implementation: Real-Time Chat
We use `react-native-gifted-chat`, the industry standard for chat UIs.

```javascript
// src/components/ChatScreen.js
import React, { useState, useEffect, useCallback } from 'react';
import { GiftedChat } from 'react-native-gifted-chat';
import { collection, addDoc, query, orderBy, onSnapshot } from 'firebase/firestore';
import { db } from '../services/firebase';

export function ChatScreen() {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    const q = query(collection(db, 'messages'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setMessages(snapshot.docs.map(doc => ({
        _id: doc.id,
        ...doc.data()
      })));
    });
    return unsubscribe;
  }, []);

  const onSend = useCallback((messages = []) => {
    const { _id, createdAt, text, user } = messages[0];
    addDoc(collection(db, 'messages'), { _id, createdAt, text, user });
  }, []);

  return <GiftedChat messages={messages} onSend={onSend} user={{ _id: 1 }} />;
}
```

