In your React Native app, use `react-native-gifted-chat` for the UI and `socket.io-client` for connectivity.

```javascript
import { GiftedChat } from 'react-native-gifted-chat';
import io from 'socket.io-client';

const socket = io('http://your-server-url:3000');

export default function ChatScreen({ chatId }) {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    socket.emit('join_chat', chatId);
    socket.on('receive_message', (msg) => {
      setMessages(prev => GiftedChat.append(prev, msg));
    });
  }, []);

  const onSend = (newMessages = []) => {
    socket.emit('send_message', newMessages[0]);
    setMessages(prev => GiftedChat.append(prev, newMessages));
  };

  return <GiftedChat messages={messages} onSend={onSend} />;
}
```

