const subscribeToMessages = (callback) => {
  const q = query(collection(db, "messages"), orderBy("timestamp", "asc"));
  return onSnapshot(q, (snapshot) => {
    const msgs = snapshot.docs.map(doc => doc.data());
    callback(msgs);
  });
};
```

