import { GiftedChat } from 'react-native-gifted-chat';
import firestore from '@react-native-firebase/firestore';

export default function ChatScreen() {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    // Real-time listener
    const unsubscribe = firestore().collection('messages')
      .orderBy('createdAt', 'desc')
      .onSnapshot(snapshot => {
        setMessages(snapshot.docs.map(doc => ({ _id: doc.id, ...doc.data() })));
      });
    return unsubscribe;
  }, []);

  const onSend = (newMsg) => {
    firestore().collection('messages').add(newMsg[0]);
  };

  return <GiftedChat messages={messages} onSend={onSend} user={{_id: 1}} />;
}
```

