    const { text } = newMessages[0];
    firestore().collection('messages').add({
      text,
      createdAt: firestore.FieldValue.serverTimestamp(),
    });
  };

  return <GiftedChat messages={messages} onSend={onSend} user={{ _id: 1 }} />;
}
