import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

function App() {
  const [data, setData] = useState([]);
  const [threshold, setThreshold] = useState(80);
  const [inputValue, setInputValue] = useState(80);

  // Simulate real-time data stream
  useEffect(() => {
    const interval = setInterval(() => {
      const newDataPoint = {
        name: new Date().toLocaleTimeString().slice(-8),
        value: Math.floor(Math.random() * 100),
      };
      setData((prevData) => [...prevData.slice(-19), newDataPoint]);
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  const handleUpdate = (e) => {
    e.preventDefault();
    setThreshold(Number(inputValue));
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>Real-Time Dashboard</h1>

      {/* Form Handling */}
      <form onSubmit={handleUpdate} style={{ marginBottom: '20px' }}>
        <label>Alert Threshold: </label>
        <input 
          type="number" 
          value={inputValue} 
          onChange={(e) => setInputValue(e.target.value)} 
        />
        <button type="submit">Update</button>
      </form>

      {/* Visualisation */}
      <div style={{ width: '100%', height: 400, background: '#f4f4f4', padding: '10px' }}>
        <ResponsiveContainer>
          <LineChart data={data}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="name" />
            <YAxis domain={[0, 100]} />
            <Tooltip />
            <Line type="monotone" dataKey="value" stroke="#8884d8" strokeWidth={2} />
            {/* Reference line for the threshold */}
            <line x1="0" x2="100%" y1={threshold} y2={threshold} stroke="red" strokeDasharray="5 5" />
          </LineChart>
        </ResponsiveContainer>
      </div>

      <p>Current Threshold Setting: <strong>{threshold}</strong></p>
    </div>
  );
}

export default App;
```

### Key Components Explained:

1.  **`useEffect` (Real-time logic):** 
    *   This sets up an interval that pushes a new object into the state every 2 seconds.
    *   `prevData.slice(-19)` ensures the chart only keeps the last 20 points, preventing memory bloat and keeping the chart readable.
2.  **`Recharts`:** 
    *   This is a highly declarative library. By passing the `data` array into `<LineChart />`, the UI updates automatically whenever the state changes.
    *   `ResponsiveContainer` ensures the chart resizes if the user changes their browser window size.
3.  **Form Handling:**
    *   We use a controlled input (`inputValue`) to hold the draft value.
    *   The `handleUpdate` function processes the form submission to lock in the new threshold, demonstrating how state flows from a user input to the visualization.

### Suggestions for Professionalizing:
*   **WebSockets:** Replace `setInterval` with a WebSocket connection (using `socket.io-client`) to pull live data from a backend server rather than generating random numbers.
*   **State Management:** For larger dashboards, consider using **Zustand** or **Redux Toolkit** to manage the data store across multiple dashboard widgets.
*   **Styling:** Integrate **Tailwind CSS** for faster layout design.
*   **Performance:** If the data stream is extremely fast (e.g., 60fps), use `useMemo` to memoize the chart data or throttle the state updates.

