### 2. The Logic (`script.js`)
```javascript
// Initialize Chart
const ctx = document.getElementById('myChart').getContext('2d');
const myChart = new Chart(ctx, {
    type: 'line',
    data: {
        labels: ['Now'],
        datasets: [{ label: 'Live Metrics', data: [10], borderColor: 'blue' }]
    }
});

// Function to handle form submission
function addData() {
    const val = document.getElementById('dataInput').value;
    updateChart(val);
}

// Function to update chart
function updateChart(value) {
    const time = new Date().toLocaleTimeString();
    myChart.data.labels.push(time);
    myChart.data.datasets[0].data.push(value);

    // Keep only last 10 points
    if(myChart.data.labels.length > 10) {
        myChart.data.labels.shift();
        myChart.data.datasets[0].data.shift();
    }
    myChart.update();
}

// Simulation: Auto-update every 2 seconds
setInterval(() => {
    const randomVal = Math.floor(Math.random() * 50);
    updateChart(randomVal);
}, 2000);
```

