const width = 900;
const height = 600;

// 1. Setup SVG with Zoom behavior
const svg = d3.select("#heatmap")
  .append("svg")
  .attr("width", width)
  .attr("height", height)
  .call(d3.zoom().on("zoom", (event) => {
    container.attr("transform", event.transform);
  }));

const container = svg.append("g");

// 2. Initialize Treemap Layout
const treemap = d3.treemap()
  .size([width, height])
  .padding(1);

function updateHeatmap(data) {
  const root = d3.hierarchy({children: data})
    .sum(d => d.marketCap)
    .sort((a, b) => b.value - a.value);

  treemap(root);

  const cells = container.selectAll("g")
    .data(root.leaves(), d => d.data.symbol);

  // Enter/Update pattern
  const enterCells = cells.enter().append("g");

  enterCells.append("rect")
    .attr("fill", d => d.data.change > 0 ? "#26a69a" : "#ef5350");

  enterCells.append("text")
    .attr("x", 5).attr("y", 20)
    .text(d => d.data.symbol);

  // Update positions
  cells.merge(enterCells).select("rect")
    .attr("x", d => d.x0)
    .attr("y", d => d.y0)
    .attr("width", d => d.x1 - d.x0)
    .attr("height", d => d.y1 - d.y0);
}

// 3. Simulate Real-Time Updates
function refreshData() {
  const mockData = [
    { symbol: "AAPL", marketCap: 2500, change: Math.random() * 4 - 2 },
    { symbol: "TSLA", marketCap: 800, change: Math.random() * 4 - 2 },
    { symbol: "NVDA", marketCap: 1200, change: Math.random() * 4 - 2 }
  ];
  updateHeatmap(mockData);
}

setInterval(refreshData, 3000);
```

### 3. Key Considerations for Production

#### A. Data Source
*   **WebSockets:** Instead of `setInterval`, use WebSockets (e.g., [Finnhub WebSocket](https://finnhub.io/docs/api/websocket-trades)) to receive price ticks as they happen.
*   **Throttling:** Do not re-render the entire D3 tree on every tick. Buffer the ticks and update the UI at a maximum of 1-2 FPS to ensure the browser remains responsive.

#### B. Zoom/Pan
*   The `d3.zoom()` implementation provided applies to the entire container. If you want the tiles to stay "fixed" while the user zooms into the map, ensure your `rect` attributes are scaled relative to the `event.transform.k` (scale factor).

#### C. Performance Optimization
*   **Canvas vs SVG:** If you are rendering more than 500 stocks, move from `SVG` to `HTML5 Canvas`. SVG creates a DOM element for every rectangle, which will crash the browser if the data set is large.
*   **Transitions:** Use `d3.transition()` to animate the tiles smoothly when prices change, rather than "snapping" the colors.

