### 2. The Implementation

```jsx
import React, { useState, useEffect, useMemo } from 'react';
import { Treemap, ResponsiveContainer, Tooltip } from 'recharts';
import { scaleLinear } from 'd3-scale';

// Generate mock initial data
const initialData = Array.from({ length: 20 }, (_, i) => ({
  name: `TICK${i}`,
  price: Math.random() * 500 + 50,
  change: (Math.random() - 0.5) * 10, // -5% to +5%
  size: Math.random() * 1000,
}));

const StockHeatmap = () => {
  const [data, setData] = useState(initialData);

  // Real-time update simulation
  useEffect(() => {
    const interval = setInterval(() => {
      setData((prev) =>
        prev.map((item) => ({
          ...item,
          change: item.change + (Math.random() - 0.5),
        }))
      );
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  // Color logic: Red for negative, Green for positive
  const colorScale = useMemo(() => 
    scaleLinear().domain([-5, 0, 5]).range(['#ff4d4f', '#262626', '#52c41a']), 
  []);

  const CustomizedContent = (props) => {
    const { x, y, width, height, name, change } = props;
    const color = colorScale(change);

    return (
      <g>
        <rect x={x} y={y} width={width} height={height} fill={color} stroke="#fff" />
        {width > 40 && height > 30 && (
          <text x={x + 5} y={y + 20} fill="#fff" fontSize={12}>
            {name}
          </text>
        )}
      </g>
    );
  };

  return (
    <div style={{ width: '100%', height: '500px', background: '#000', padding: '20px' }}>
      <h2 style={{ color: '#fff' }}>Market Heatmap (Real-time)</h2>
      <ResponsiveContainer>
        <Treemap
          data={data}
          dataKey="size"
          aspectRatio={4 / 3}
          stroke="#fff"
          content={<CustomizedContent />}
        >
          <Tooltip formatter={(value, name, props) => [props.payload.change.toFixed(2) + '%', 'Change']} />
        </Treemap>
      </ResponsiveContainer>
    </div>
  );
};

export default StockHeatmap;
```

### Key Technical Features:

1.  **D3 Color Interpolation**: We use `d3-scale` to map percentage changes to a color spectrum. Negative values map to red (`#ff4d4f`), zero to dark grey, and positive values to green (`#52c41a`).
2.  **Responsive Treemap**: The `ResponsiveContainer` ensures the heatmap resizes automatically with the browser window (providing the "responsive" aspect of interaction).
3.  **Real-time Updates**: The `useEffect` hook triggers a state update every 2 seconds. Because React triggers a re-render of the component when state changes, the `Treemap` updates its colors dynamically without a full page reload.
4.  **Custom Content**: By overriding `content` in the `<Treemap />` component, we inject custom SVG logic to handle the dynamic coloring of each cell based on the `change` prop.

