```javascript
import * as d3 from 'd3';

const canvas = document.getElementById('heatmap-canvas');
const context = canvas.getContext('2d');
const width = 800;
const height = 600;

// Mock Data Structure
let data = Array.from({ length: 100 }, (_, i) => ({
  symbol: `STK${i}`,
  price: Math.random() * 100,
  change: (Math.random() - 0.5) * 10, // -5% to +5%
}));

// Color Scale: Red (Negative) -> Grey (Neutral) -> Green (Positive)
const colorScale = d3.scaleLinear()
  .domain([-5, 0, 5])
  .range(['#ff4d4d', '#444', '#2ecc71']);

// Zoom/Pan Handler
let transform = d3.zoomIdentity;

const zoom = d3.zoom()
  .scaleExtent([1, 10])
  .on('zoom', (event) => {
    transform = event.transform;
    draw();
  });

d3.select(canvas).call(zoom);

function draw() {
  context.clearRect(0, 0, width, height);

  // Calculate grid layout
  const cols = 10;
  const size = 70;

  context.save();
  context.translate(transform.x, transform.y);
  context.scale(transform.k, transform.k);

  data.forEach((d, i) => {
    const x = (i % cols) * (size + 5);
    const y = Math.floor(i / cols) * (size + 5);

    context.fillStyle = colorScale(d.change);
    context.fillRect(x, y, size, size);

    // Label
    context.fillStyle = 'white';
    context.font = '10px Arial';
    context.fillText(d.symbol, x + 5, y + 20);
    context.fillText(`${d.change.toFixed(2)}%`, x + 5, y + 40);
  });

  context.restore();
}

// Real-time update simulation
setInterval(() => {
  data.forEach(d => {
    d.change += (Math.random() - 0.5); // Random fluctuation
  });
  draw();
}, 2000);

draw();
```

