### 2. The Implementation

```html
<div id="heatmap" style="width: 100vw; height: 90vh; overflow: hidden; background: #111;"></div>

<script>
const width = window.innerWidth;
const height = window.innerHeight;

// 1. Initialize SVG with Zoom
const svg = d3.select("#heatmap")
  .append("svg")
  .attr("width", width)
  .attr("height", height)
  .call(d3.zoom().scaleExtent([0.5, 5]).on("zoom", (event) => {
    container.attr("transform", event.transform);
  }))
  .append("g");

const container = svg.append("g");

// 2. Mock Data Generator
let data = {
  name: "Market",
  children: [
    { name: "AAPL", value: 100, change: 0.02 },
    { name: "TSLA", value: 80, change: -0.05 },
    { name: "GOOG", value: 90, change: 0.01 },
    { name: "AMZN", value: 70, change: -0.01 }
  ]
};

function updateHeatmap() {
  // Update values randomly to simulate market movement
  data.children.forEach(d => d.value += (Math.random() - 0.5) * 10);

  const root = d3.hierarchy(data)
    .sum(d => d.value)
    .sort((a, b) => b.value - a.value);

  d3.treemap().size([width, height]).padding(2)(root);

  // Bind Data
  const nodes = container.selectAll("g").data(root.leaves(), d => d.data.name);

  const entering = nodes.enter().append("g");
  entering.append("rect").attr("stroke", "#000");
  entering.append("text").attr("fill", "white").attr("x", 5).attr("y", 20);

  // Update logic
  const allNodes = entering.merge(nodes);
  allNodes.select("rect")
    .transition().duration(500)
    .attr("x", d => d.x0)
    .attr("y", d => d.y0)
    .attr("width", d => d.x1 - d.x0)
    .attr("height", d => d.y1 - d.y0)
    .attr("fill", d => d.data.change > 0 ? "green" : "red");

  allNodes.select("text")
    .attr("x", d => d.x0 + 5)
    .attr("y", d => d.y0 + 20)
    .text(d => `${d.data.name} (${d.data.value.toFixed(0)})`);
}

// 3. Start Loop
setInterval(updateHeatmap, 2000);
updateHeatmap();
</script>
```

### Key Architectural Decisions:

1.  **D3.js Treemap Layout**: This is the industry standard for heatmaps. It automatically calculates the optimal rectangle sizes based on market cap or volume values.
2.  **`d3.zoom()`**: This provides the pan/zoom functionality out of the box. By applying it to the `svg` element and transforming a child `g` container, the entire visualization remains interactive regardless of the zoom scale.
3.  **Data-Driven Updates**: Instead of destroying and recreating the DOM, we use the D3 **General Update Pattern** (`data.children.forEach` + `.merge(nodes)`). This makes the animation smooth when stock prices fluctuate.
4.  **Performance Tip**: If you reach 500+ stocks, switch the rendering from `SVG` to `HTML5 Canvas`. SVG creates a DOM node for every box, which will lag if you have thousands of elements. For a dashboard with 50-100 stocks, this SVG implementation is perfectly performant.

