        const size = 10; // 10x10 grid
        const cellSize = 50;
        let data = Array.from({length: size * size}, () => Math.random());

        // Zoom/Pan logic
        let transform = d3.zoomIdentity;
        const zoom = d3.zoom().scaleExtent([1, 8]).on('zoom', (e) => {
            transform = e.transform;
            draw();
        });
