This example uses a `d3.zoom` transform to manipulate a Canvas element, simulating a real-time price feed.

```html
<!DOCTYPE html>
<html>
<head>
    <script src="https://d3js.org/d3.v7.min.js"></script>
    <style> canvas { cursor: crosshair; border: 1px solid #ccc; } </style>
</head>
<body>
    <canvas id="heatmap" width="800" height="600"></canvas>

    <script>
        const canvas = document.getElementById('heatmap');
        const ctx = canvas.getContext('2d');
        const size = 20; // grid size
        let data = Array.from({length: 400}, (_, i) => ({ val: Math.random() }));

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            data.forEach((d, i) => {
                const x = (i % 20) * size, y = Math.floor(i / 20) * size;
                ctx.fillStyle = d3.interpolateRdYlGn(d.val);
                ctx.fillRect(x, y, size - 1, size - 1);
            });
        }

        // Zoom/Pan logic
        const zoom = d3.zoom().scaleExtent([1, 8]).on('zoom', (e) => {
            ctx.setTransform(e.transform.k, 0, 0, e.transform.k, e.transform.x, e.transform.y);
            draw();
        });
        d3.select(canvas).call(zoom);

        // Simulate Real-time updates
        setInterval(() => {
            data[Math.floor(Math.random() * data.length)].val = Math.random();
            draw();
        }, 100);

        draw();
    </script>
</body>
</html>
```

