            .attr("viewBox", `0 0 ${width} ${height}`);

        const g = svg.append("g");

        // 1. Setup Zoom/Pan
        const zoom = d3.zoom().scaleExtent([1, 8]).on("zoom", (e) => g.attr("transform", e.transform));
        svg.call(zoom);

        // 2. Generate initial data
        let data = Array.from({length: 50}, (_, i) => ({
            id: i, x: (i % 7) * 100, y: Math.floor(i / 7) * 100,
            price: Math.random() * 100
        }));

        // 3. Render function
        function update() {
            const rects = g.selectAll("rect").data(data, d => d.id);

            rects.enter().append("rect")
                .attr("class", "cell").attr("width", 90).attr("height", 90)
                .merge(rects)
                .attr("x", d => d.x).attr("y", d => d.y)
                .attr("fill", d => d3.interpolateRdYlGn(d.price / 100));
        }

        // 4. Simulate real-time updates
        setInterval(() => {
            data.forEach(d => d.price = Math.max(0, Math.min(100, d.price + (Math.random() - 0.5) * 10)));
            update();
        }, 1000);

        update();
    </script>
</body>
</html>
```

### Key Technical Components:

1.  **D3 Zoom Behavior:** The `d3.zoom()` function attaches listener events to the SVG. When you scroll or drag, it calculates a transformation matrix (`e.transform`) that we apply to the group element (`g`) containing all our rects. This is much more performant than redrawing elements.
2.  **Data Binding:** The `g.selectAll("rect").data(data, d => d.id)` pattern ensures that D3 only updates existing elements rather than recreating the entire DOM every second.
3.  **Real-Time Simulation:** We use `setInterval` to mutate the data object directly and call `update()` to refresh the color scale.
4.  **Scalability:** 
    *   **Performance:** By using `viewBox` and `transform`, the browser leverages GPU-accelerated rendering for the panning/zooming.
    *   **Color Scale:** `d3.interpolateRdYlGn` is a built-in function that automatically transitions colors from Red (low) to Yellow (neutral) to Green (high).

### How to use this in production:
*   **WebSockets:** Replace the `setInterval` logic with a WebSocket listener (`socket.onmessage`) to ingest actual live market data feeds.
