### 2. The Task Board Component (`Board.js`)
This component uses `dnd-kit` to handle interaction and Firestore snapshots to sync changes across users in real-time.

```jsx
import React, { useEffect, useState } from 'react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { arrayMove, SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { collection, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { db } from './firebase';
import TaskItem from './TaskItem';

const Board = () => {
  const [tasks, setTasks] = useState([]);

  // Real-time listener
  useEffect(() => {
    const unsub = onSnapshot(collection(db, "tasks"), (snapshot) => {
      setTasks(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
    return unsub;
  }, []);

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      const oldIndex = tasks.findIndex(t => t.id === active.id);
      const newIndex = tasks.findIndex(t => t.id === over.id);

      const newTasks = arrayMove(tasks, oldIndex, newIndex);
      setTasks(newTasks);

      // Update order in Firebase
      newTasks.forEach(async (task, index) => {
        await updateDoc(doc(db, "tasks", task.id), { order: index });
      });
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div className="board">
        <SortableContext items={tasks} strategy={verticalListSortingStrategy}>
          {tasks.sort((a, b) => a.order - b.order).map(task => (
            <TaskItem key={task.id} task={task} />
          ))}
        </SortableContext>
      </div>
    </DndContext>
  );
};
```

