// 1. Firebase Config (Get this from your Firebase console)
const firebaseConfig = { apiKey: "...", databaseURL: "..." };
firebase.initializeApp(firebaseConfig);
const db = firebase.database().ref('tasks');

// 2. Add Task to Firebase
