  const text = document.getElementById('taskInput').value;
  db.push({ text: text, status: 'todo' });
}

// 3. Real-time Listener (Syncs UI when database changes)
db.on('value', (snapshot) => {
  const tasks = snapshot.val();
  document.querySelectorAll('.column div').forEach(el => el.remove()); // Clear UI

  for (let id in tasks) {
    const task = tasks[id];
    const div = document.createElement('div');
    div.className = "bg-white p-2 mb-2 shadow cursor-move";
    div.innerText = task.text;
    div.id = id;
    div.draggable = true;
    div.ondragstart = (e) => e.dataTransfer.setData("text", id);
    document.getElementById(task.status).appendChild(div);
  }
});

// 4. Handle Drag and Drop
function allowDrop(e) { e.preventDefault(); }

function drop(e) {
  e.preventDefault();
  const id = e.dataTransfer.getData("text");
  const newStatus = e.currentTarget.id;

  // Update status in Firebase
  db.child(id).update({ status: newStatus });
}
```

