import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable } from '@hello-pangea/dnd';
import { db } from './firebase';
import { doc, getDoc, setDoc } from 'firebase/firestore';

const initialData = {
  todo: { id: 'todo', title: 'To Do', items: [{ id: '1', content: 'Task 1' }] },
  done: { id: 'done', title: 'Done', items: [] }
};

export default function App() {
  const [columns, setColumns] = useState(initialData);

  const onDragEnd = (result) => {
    if (!result.destination) return;
    const { source, destination } = result;

    const sourceCol = columns[source.droppableId];
    const destCol = columns[destination.droppableId];

    // Logic to move items between arrays
    const newSourceItems = [...sourceCol.items];
    const [removed] = newSourceItems.splice(source.index, 1);

    const newDestItems = [...destCol.items];
    newDestItems.splice(destination.index, 0, removed);

    setColumns({
      ...columns,
      [source.droppableId]: { ...sourceCol, items: newSourceItems },
      [destination.droppableId]: { ...destCol, items: newDestItems }
    });
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div style={{ display: 'flex', gap: '20px', padding: '20px' }}>
        {Object.values(columns).map(column => (
