To create a minimal working version of a real-time collaborative task board, we will use **HTML5 Drag and Drop API** for the UI and **Firebase (Realtime Database)** as the backend. Firebase handles the "real-time" aspect automatically—when one user moves a card, it updates for everyone else instantly.

### Prerequisites
1. Create a project at [Firebase Console](https://console.firebase.google.com/).
2. Enable **Realtime Database** (start in Test Mode).
3. Copy your Firebase config object.

### The Code (`index.html`)

```html
<!DOCTYPE html>
<html>
<head>
    <style>
        .board { display: flex; gap: 20px; padding: 20px; }
        .column { width: 200px; background: #eee; padding: 10px; min-height: 400px; }
        .card { background: white; padding: 10px; margin: 10px 0; cursor: grab; border: 1px solid #ccc; }
    </style>
</head>
<body>

<div class="board">
    <div class="column" id="todo" ondrop="drop(event)" ondragover="allowDrop(event)"><h3>To Do</h3></div>
    <div class="column" id="done" ondrop="drop(event)" ondragover="allowDrop(event)"><h3>Done</h3></div>
</div>

<script type="module">
    import { initializeApp } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js";
    import { getDatabase, ref, onValue, set } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-database.js";

    const firebaseConfig = { /* PASTE YOUR FIREBASE CONFIG HERE */ };
    const db = getDatabase(initializeApp(firebaseConfig));

    // Drag and Drop Logic
    window.allowDrop = (e) => e.preventDefault();
    window.drag = (e) => e.dataTransfer.setData("text", e.target.id);

    window.drop = (e) => {
        const id = e.dataTransfer.getData("text");
        const newStatus = e.target.closest('.column').id;
        set(ref(db, 'tasks/' + id + '/status'), newStatus); // Update Firebase
    };

    // Real-time Sync
    onValue(ref(db, 'tasks'), (snapshot) => {
        const tasks = snapshot.val();
        document.querySelectorAll('.column').forEach(col => col.innerHTML = `<h3>${col.id}</h3>`);
        for (let id in tasks) {
            const card = document.createElement('div');
            card.className = 'card';
            card.id = id;
            card.draggable = true;
            card.innerText = tasks[id].text;
            card.ondragstart = window.drag;
            document.getElementById(tasks[id].status).appendChild(card);
        }
    });
</script>
</body>
</html>
```

