### 3. The Implementation (app.js)
This script handles fetching data, real-time updates, and the drag-and-drop persistence.

```javascript
const supabase = supabase.createClient('YOUR_SUPABASE_URL', 'YOUR_SUPABASE_KEY');

// 1. Render Tasks
async function fetchTasks() {
  const { data } = await supabase.from('tasks').select('*');
  document.getElementById('board').innerHTML = renderBoard(data);
  initSortable();
}

// 2. Real-time Subscription
supabase.channel('tasks').on('postgres_changes', { event: '*', schema: 'public', table: 'tasks' }, 
  () => fetchTasks()).subscribe();

// 3. Drag and Drop Logic
function initSortable() {
  document.querySelectorAll('.column').forEach(col => {
    new Sortable(col, {
      group: 'shared',
      onEnd: async (evt) => {
        const taskId = evt.item.dataset.id;
        const newStatus = evt.to.dataset.status;
        await supabase.from('tasks').update({ status: newStatus }).eq('id', taskId);
      }
    });
  });
}

fetchTasks();
```

