This is the core of an exchange or order gateway: a fast queue to pass market data or orders between threads.

```cpp
#include <atomic>
#include <vector>
#include <iostream>

// Simple SPSC Lock-Free Ring Buffer
template<typename T, size_t Capacity>
class LockFreeQueue {
private:
    T buffer[Capacity];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool push(const T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Capacity;
        if (next_t == head.load(std::memory_order_acquire)) return false; // Full
        buffer[t] = item;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false; // Empty
        item = buffer[h];
        head.store((h + 1) % Capacity, std::memory_order_release);
        return true;
    }
};

struct Order {
    int orderId;
    double price;
    int quantity;
};
```

