```cpp
#include <atomic>
#include <vector>

template<typename T, size_t Size>
class RingBuffer {
    std::atomic<size_t> write_idx{0};
    std::atomic<size_t> read_idx{0};
    T buffer[Size];

public:
    bool try_push(const T& item) {
        size_t current_write = write_idx.load(std::memory_order_relaxed);
        if (current_write - read_idx.load(std::memory_order_acquire) >= Size) return false;
        buffer[current_write % Size] = item;
        write_idx.store(current_write + 1, std::memory_order_release);
        return true;
    }

    bool try_pop(T& item) {
        size_t current_read = read_idx.load(std::memory_order_relaxed);
        if (current_read == write_idx.load(std::memory_order_acquire)) return false;
        item = buffer[current_read % Size];
        read_idx.store(current_read + 1, std::memory_order_release);
        return true;
    }
};
```

