    int id;
    double price;
    int quantity;
    bool active;
};

// Simple Ring Buffer (Single Producer, Single Consumer)
class LockFreeQueue {
    static constexpr size_t SIZE = 1024;
    Order buffer[SIZE];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(Order o) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next = (t + 1) % SIZE;
        if (next == head.load(std::memory_order_acquire)) return false; // Full
        buffer[t] = o;
        tail.store(next, std::memory_order_release);
        return true;
    }

    bool pop(Order& o) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false; // Empty
        o = buffer[h];
        head.store((h + 1) % SIZE, std::memory_order_release);
        return true;
    }
};

// The "Hot Path" (Business Logic)
void execution_engine(LockFreeQueue& q) {
    Order o;
    while (true) {
        if (q.pop(o)) {
            // Logic: Match orders against book
            // Minimize branching here for CPU pipelining
        }
    }
}

int main() {
    LockFreeQueue queue;
    std::thread engine(execution_engine, std::ref(queue));

    // Simulate Gateway receiving an order
    queue.push({1, 150.25, 100, true});

    engine.join();
    return 0;
}
```

