### 1. The Lock-Free Ring Buffer (The Foundation)
To achieve low latency, avoid `std::mutex`. Use a Single-Producer Single-Consumer (SPSC) queue.

```cpp
#include <atomic>
#include <vector>

template<typename T, size_t Size>
class SPSCQueue {
    T buffer[Size];
    std::atomic<size_t> head{0}, tail{0};
public:
    bool push(const T& value) {
        size_t t = tail.load(std::memory_order_relaxed);
        if ((t + 1) % Size == head.load(std::memory_order_acquire)) return false;
        buffer[t] = value;
        tail.store((t + 1) % Size, std::memory_order_release);
        return true;
    }
    bool pop(T& value) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        value = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};
```

### 2. The Core Engine (Strategy Thread)
This thread is pinned to a specific CPU core. It performs no system calls, no memory allocation, and no I/O.

```cpp
