    private final Histogram latencyStats = new Histogram(3600000000000L, 3);

    public void runPublisher() {
        // Use an embedded Media Driver for lowest latency
        final MediaDriver driver = MediaDriver.launchEmbedded();
        final Aeron aeron = Aeron.connect();
        final Publication publication = aeron.addPublication("aeron:udp?endpoint=localhost:20121", 10);

