            // Try-claim the buffer (Zero Copy)
            long result = publication.offer(buffer, 0, buffer.length);

            if (result > 0) {
                long latency = System.nanoTime() - startTime;
                latencyStats.recordValue(latency);
            }
        }
    }
}
