#include <atomic>
#include <vector>
#include <chrono>

// Align to cache line size to prevent false sharing
struct alignas(64) Message {
    uint64_t id;
    uint64_t timestamp_ns;
    char payload[64];
};

class RingBuffer {
    static constexpr size_t Size = 1 << 20; // Must be power of 2
    Message buffer[Size];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) & (Size - 1);
        if (next_t == head.load(std::memory_order_acquire)) return false;
        buffer[t] = msg;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h];
        head.store((h + 1) & (Size - 1), std::memory_order_release);
        return true;
    }
};
```

