```java
import com.lmax.disruptor.dsl.Disruptor;
import com.lmax.disruptor.RingBuffer;
import java.util.concurrent.Executors;

public class HighFrequencyRouter {
    private final RingBuffer<MessageEvent> ringBuffer;

    public HighFrequencyRouter(int bufferSize) {
        // Use a single-threaded claim strategy for lowest latency
        Disruptor<MessageEvent> disruptor = new Disruptor<>(
            MessageEvent::new, 
            bufferSize, 
            Executors.defaultThreadFactory()
        );

        // Attach the consumer (The Router)
        disruptor.handleEventsWith((event, sequence, endOfBatch) -> {
            long latency = System.nanoTime() - event.getTimestamp();
            routeMessage(event.getPayload(), latency);
        });

        this.ringBuffer = disruptor.start();
    }

    public void onData(byte[] payload) {
        long sequence = ringBuffer.next();
        try {
            MessageEvent event = ringBuffer.get(sequence);
            event.setPayload(payload);
            event.setTimestamp(System.nanoTime()); // Start latency monitor
        } finally {
            ringBuffer.publish(sequence);
        }
    }
}
```

