```cpp
#include <vector>
#include <atomic>

template<size_t Size>
class RingBuffer {
    Message buffer[Size];
    std::atomic<size_t> write_idx{0};
    std::atomic<size_t> read_idx{0};

public:
    bool try_push(const Message& msg) {
        size_t head = write_idx.load(std::memory_order_relaxed);
        size_t next = (head + 1) % Size;
        if (next == read_idx.load(std::memory_order_acquire)) return false;

        buffer[head] = msg;
        write_idx.store(next, std::memory_order_release);
        return true;
    }

    bool try_pop(Message& msg) {
        size_t tail = read_idx.load(std::memory_order_relaxed);
        if (tail == write_idx.load(std::memory_order_acquire)) return false;

        msg = buffer[tail];
        read_idx.store((tail + 1) % Size, std::memory_order_release);
        return true;
    }
};
