use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};
use crossbeam_channel::{bounded, Receiver, Sender};
use std::thread;

const BATCH_SIZE: usize = 1024;

struct Message {
    id: u64,
    timestamp: u64, // Nanoseconds since epoch
    payload: [u8; 32],
}

// Atomic latency tracker
static TOTAL_LATENCY: AtomicU64 = AtomicU64::new(0);
static MSG_COUNT: AtomicU64 = AtomicU64::new(0);

fn producer(tx: Sender<Message>) {
    let mut id = 0;
    loop {
        let msg = Message {
            id,
            timestamp: Instant::now().elapsed().as_nanos() as u64,
            payload: [0; 32],
        };
        let _ = tx.send(msg);
        id += 1;
    }
}

fn router(rx: Receiver<Message>) {
    loop {
        // High-frequency batch processing
        if let Ok(msg) = rx.recv() {
            let now = Instant::now().elapsed().as_nanos() as u64;
            let latency = now - msg.timestamp;

            // Update metrics non-blockingly
            TOTAL_LATENCY.fetch_add(latency, Ordering::Relaxed);
            MSG_COUNT.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn main() {
    let (tx, rx) = bounded::<Message>(10_000);

    // Spawn producer thread
    thread::spawn(move || producer(tx));

    // Spawn router thread
    thread::spawn(move || router(rx));

    // Monitoring thread
    loop {
        thread::sleep(Duration::from_secs(1));
        let count = MSG_COUNT.swap(0, Ordering::Relaxed);
        let lat = TOTAL_LATENCY.swap(0, Ordering::Relaxed);

        if count > 0 {
            println!("Throughput: {} msg/s | Avg Latency: {} ns", 
                count, lat / count);
        }
    }
}
