#include <iostream>
#include <atomic>
#include <vector>
#include <thread>
#include <chrono>

// High-performance ring buffer slot
struct Message {
    uint64_t id;
    uint64_t timestamp_ns;
    char payload[64];
};

const size_t RING_SIZE = 1024 * 64; // Must be power of 2
Message ring_buffer[RING_SIZE];
std::atomic<size_t> write_idx{0};
std::atomic<size_t> read_idx{0};

// Producer: Injects messages and logs start time
void producer() {
    uint64_t count = 0;
    while (true) {
        size_t idx = write_idx.load(std::memory_order_relaxed);
        size_t next = (idx + 1) % RING_SIZE;

        if (next != read_idx.load(std::memory_order_acquire)) {
            ring_buffer[idx] = {count++, (uint64_t)std::chrono::steady_clock::now().time_since_epoch().count(), "data"};
            write_idx.store(next, std::memory_order_release);
        }
    }
}

// Consumer: Routes messages and calculates latency
void consumer() {
    uint64_t total_latency = 0;
    uint64_t count = 0;

    while (true) {
        size_t idx = read_idx.load(std::memory_order_relaxed);
        if (idx != write_idx.load(std::memory_order_acquire)) {
            auto& msg = ring_buffer[idx];

            // Calculate Latency
            uint64_t now = std::chrono::steady_clock::now().time_since_epoch().count();
            total_latency += (now - msg.timestamp_ns);
            count++;

            read_idx.store((idx + 1) % RING_SIZE, std::memory_order_release);

            if (count % 1000000 == 0) {
                std::cout << "Avg Latency (ns): " << (total_latency / count) << std::endl;
            }
        }
    }
}

int main() {
    std::thread t1(producer);
    std::thread t2(consumer);
    t1.join(); t2.join();
    return 0;
}
```

