### Minimal Implementation (C++17)

```cpp
#include <iostream>
#include <atomic>
#include <vector>
#include <thread>
#include <chrono>

// Fixed-size message structure
struct Message {
    uint64_t id;
    uint64_t timestamp;
    char payload[64];
};

// Simplified Lock-Free Ring Buffer
class RingBuffer {
    static constexpr size_t SIZE = 1 << 20; // 1M slots
    Message buffer[SIZE];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool try_push(uint64_t id) {
        size_t t = tail.load(std::memory_order_relaxed);
        if (t - head.load(std::memory_order_acquire) >= SIZE) return false;
        buffer[t % SIZE] = {id, __builtin_ia32_rdtsc(), "data"};
        tail.store(t + 1, std::memory_order_release);
        return true;
    }

    bool try_pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h % SIZE];
        head.store(h + 1, std::memory_order_release);
        return true;
    }
};

// Producer / Consumer logic
void consumer(RingBuffer& rb) {
    uint64_t total_latency = 0;
    uint64_t count = 0;
    Message m;
    while (true) {
        if (rb.try_pop(m)) {
            uint64_t now = __builtin_ia32_rdtsc();
            total_latency += (now - m.timestamp);
            if (++count % 1000000 == 0) {
                std::cout << "Avg Latency (cycles): " << total_latency / count << std::endl;
            }
        }
    }
}

int main() {
    RingBuffer rb;
    std::thread t(consumer, std::ref(rb));

    // Producer Loop
    for (uint64_t i = 0; i < 100000000; ++i) {
        while (!rb.try_push(i)) { /* busy wait */ }
    }
    return 0;
}
```

### Critical High-Frequency Principles Used:

1.  **Memory Barriers:** We use `std::memory_order_release` and `acquire` instead of default atomic locks. This ensures data is visible across CPU caches without the heavy cost of a full `std::mutex`.
2.  **Busy Waiting (Spin-locking):** Notice the `while(!rb.try_push)` loop. In HFT, we **never** put threads to sleep (e.g., `usleep` or `cv.wait`), as waking up a thread takes 5–50 microseconds, which is an eternity when targeting 1M+ MPS.
3.  **False Sharing Prevention:** In a production version, you would add `alignas(64)` to the `head` and `tail` variables to ensure they reside on different CPU cache lines, preventing "cache line bouncing."
4.  **Hardware Timestamps:** We use `__builtin_ia32_rdtsc()` to read the CPU clock cycle directly, providing nanosecond precision without calling the OS kernel (which `std::chrono::now()` often does).

