#include <atomic>
#include <vector>
#include <chrono>

struct Message {
    uint64_t id;
    uint64_t timestamp;
};

// High-performance circular buffer
const size_t RING_SIZE = 1 << 20; // Must be power of 2
Message ring[RING_SIZE];
std::atomic<size_t> write_idx{0};
std::atomic<size_t> read_idx{0};

// Producer: Extremely low latency
void producer(uint64_t count) {
    for (uint64_t i = 0; i < count; ++i) {
        size_t idx = write_idx.fetch_add(1, std::memory_order_relaxed);
        ring[idx % RING_SIZE] = {i, (uint64_t)std::chrono::high_resolution_clock::now().time_since_epoch().count()};
    }
}

// Consumer: Latency monitoring
void consumer(uint64_t count) {
    uint64_t total_latency = 0;
    for (uint64_t i = 0; i < count; ++i) {
        // Busy spin until data is available
        while (read_idx.load(std::memory_order_relaxed) == write_idx.load(std::memory_order_relaxed));

        Message m = ring[read_idx.load() % RING_SIZE];
        uint64_t now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
        total_latency += (now - m.timestamp);

        read_idx.fetch_add(1, std::memory_order_relaxed);
    }
    std::cout << "Avg Latency: " << (total_latency / count) << " ns" << std::endl;
}
```

