### 1. The Core Architecture
We use a **Single Producer, Single Consumer (SPSC) Ring Buffer**. By avoiding mutexes and locks, we prevent context switching, which is the primary cause of latency spikes.

```cpp
#include <iostream>
#include <vector>
#include <atomic>
#include <chrono>

// Fixed-size lock-free buffer
struct Message {
    uint64_t id;
    uint64_t timestamp;
    char payload[64];
};

const size_t BUFFER_SIZE = 1 << 20; // Must be power of 2
Message ring_buffer[BUFFER_SIZE];
std::atomic<size_t> head{0};
std::atomic<size_t> tail{0};

// Producer (Network Thread)
void push_message(uint64_t id) {
    size_t t = tail.load(std::memory_order_relaxed);
    ring_buffer[t & (BUFFER_SIZE - 1)].id = id;
    ring_buffer[t & (BUFFER_SIZE - 1)].timestamp = 
        std::chrono::steady_clock::now().time_since_epoch().count();
    tail.store(t + 1, std::memory_order_release);
}

// Consumer (Processing Thread)
void process_messages() {
    size_t h = head.load(std::memory_order_relaxed);
    while (true) {
        if (h < tail.load(std::memory_order_acquire)) {
            auto& msg = ring_buffer[h & (BUFFER_SIZE - 1)];

            // Latency Monitoring
            auto now = std::chrono::steady_clock::now().time_since_epoch().count();
            auto latency = now - msg.timestamp;

            // Log every 1 millionth message to keep throughput high
            if (msg.id % 1000000 == 0) 
                std::cout << "Msg: " << msg.id << " Latency: " << latency << "ns" << std::endl;

            h++;
            head.store(h, std::memory_order_release);
        }
    }
}
```

