### 2. The Code (eBPF/C)
This C code is compiled into bytecode and loaded into the NIC driver.

```c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

// BPF map to store filtering rules (e.g., Blocked IPs)
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // Source IP
    __type(value, __u8);  // Status (1 = Block)
} blocklist SEC(".maps");

SEC("xdp_prog")
int xdp_filter_forward(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) return XDP_PASS;

    // Only process IPv4
    if (eth->h_proto != bpf_htons(ETH_P_IP)) return XDP_PASS;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) return XDP_PASS;

    // 1. Packet Filtering: Check blocklist
    if (bpf_map_lookup_elem(&blocklist, &iph->saddr)) {
        return XDP_DROP;
    }

    // 2. Ultra-low latency Forwarding: 
    // Simply return XDP_TX to bounce packet back out the same NIC
    // or use bpf_redirect_map() for complex routing.
    return XDP_TX; 
}

