#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

// Simple Packet Filtering Logic
static inline int is_allowed(struct rte_mbuf *m) {
    // Add your layer 3/4 filtering logic here
    // e.g., check IP header destination, port, or magic byte
    return 1; // Return 0 to drop
}

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);

    // 2. Setup NIC ports, RX/TX queues, and Memory Pools
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 
                                    MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. Main Polling Loop (Ultra-Low Latency Loop)
    while (1) {
        struct rte_mbuf *bufs[BURST_SIZE];

        // Poll NIC for packets (Kernel Bypass)
        const uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, BURST_SIZE);

        if (unlikely(nb_rx == 0)) continue;

        uint16_t nb_tx = 0;
        struct rte_mbuf *tx_bufs[BURST_SIZE];

        for (int i = 0; i < nb_rx; i++) {
            if (is_allowed(bufs[i])) {
                // Forward the packet (or modify header)
                tx_bufs[nb_tx++] = bufs[i];
            } else {
                rte_pktmbuf_free(bufs[i]); // Drop
            }
        }

        // Send packets out immediately
        if (nb_tx > 0) {
            rte_eth_tx_burst(1, 0, tx_bufs, nb_tx);
        }
    }
    return 0;
}
```

### 3. Key Latency Optimization Strategies

To make this "ultra-low," you must apply these engineering constraints:

#### A. CPU Pinning and Isolation
The process must not be interrupted by the OS scheduler.
*   Use `isolcpus` in your GRUB configuration to reserve specific cores.
*   Use `pthread_setaffinity_np` to pin your polling thread to a physical core sharing the L3 cache of the NIC’s PCIe bus.

#### B. Hugepages
Standard 4KB memory pages cause excessive TLB (Translation Lookaside Buffer) misses. Use **1GB Hugepages** to keep your packet buffer structures in memory without frequent page table lookups.

#### C. Batching vs. Latency Trade-off
*   **`BURST_SIZE`**: Setting this to `32` is efficient for throughput, but if latency is the absolute priority, set this to `1`. This will trigger immediate `TX` after every `RX`, removing buffering delays at the cost of higher CPU overhead.

#### D. Zero-Copy
Do not copy packet data into a new buffer. DPDK `mbuf`s provide a pointer to the packet data directly within the NIC's ring buffer memory. Modify the packet in-place (e.g., swapping MAC addresses or decrementing TTL) before forwarding.

#### E. NIC Tuning
*   **Disable Flow Control:** Ensure the NIC is not doing PAUSE frame negotiation.
*   **SR-IOV:** Use SR-IOV to map the Virtual Function (VF) directly to the application, minimizing PCIe overhead.
*   **RSS (Receive Side Scaling):** Ensure traffic is distributed across cores to avoid bottlenecks, but pin specific flows to specific cores to maintain cache locality (L1/L2 cache hits are the difference between sub-microsecond and microsecond latency).

