#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define BURST_SIZE 32

static void forward_loop(uint16_t port_id) {
    struct rte_mbuf *bufs[BURST_SIZE];

    while (1) {
        // 1. Poll the NIC directly (No interrupts, zero context switch)
        uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, bufs, BURST_SIZE);

        if (unlikely(nb_rx == 0)) continue;

        uint16_t nb_tx = 0;
        for (int i = 0; i < nb_rx; i++) {
            // 2. Packet-level filtering
            // Example: Filter out anything that isn't IPv4
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(bufs[i], struct rte_ether_hdr *);
            if (eth_hdr->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4)) {
                rte_pktmbuf_free(bufs[i]);
                continue;
            }

            // 3. Forwarding (Simple reflection in this example)
            bufs[nb_tx++] = bufs[i];
        }

        // 4. Send burst
        if (nb_tx > 0) {
            rte_eth_tx_burst(port_id, 0, bufs, nb_tx);
        }
    }
}

int main(int argc, char *argv[]) {
    // EAL Initialization (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);

    // Configure NIC, Port, and Memory Pools here...
    // (Standard DPDK boilerplate omitted for brevity)

    forward_loop(0);
    return 0;
}
```

### Key Techniques for Ultra-Low Latency

To take this from "fast" to "ultra-low latency," you must implement these three architectural patterns:

#### 1. CPU Isolation (Core Pinning)
Standard OS scheduling causes latency spikes (jitter).
