### Implementation: Using AF_XDP (C/libxdp)

This example outlines the logic for filtering a packet (checking for a specific port) and forwarding it out of a different interface.

```c
#include <xdp/xsk.h>
#include <net/if.h>

// Simplified Packet Processor
void process_and_forward(struct xsk_umem_info *umem, struct xsk_socket_info *xsk) {
    uint32_t rcvd, i;
    uint64_t idx_rx, idx_tx;

    // Busy poll the RX ring
    rcvd = xsk_ring_cons__peek(&xsk->rx, BATCH_SIZE, &idx_rx);
    if (rcvd == 0) return;

    for (i = 0; i < rcvd; i++) {
        uint64_t addr = *xsk_ring_cons__rx_desc(&xsk->rx, idx_rx + i);
        uint8_t *pkt = xsk_umem__get_data(umem->buffer, addr);

        // --- PACKET FILTERING (Example: Drop if not UDP) ---
        if (!is_udp_packet(pkt)) continue;

        // --- FORWARDING ---
        // Get index from TX ring
        uint32_t idx_tx;
        xsk_ring_prod__reserve(&xsk->tx, 1, &idx_tx);

        // Copy address to TX descriptor (or reuse if zero-copy is fully set up)
        struct xdp_desc *tx_desc = xsk_ring_prod__tx_desc(&xsk->tx, idx_tx);
        tx_desc->addr = addr;
        tx_desc->len = get_pkt_len(pkt);

        xsk_ring_prod__submit(&xsk->tx, 1);
    }

    xsk_ring_cons__release(&xsk->rx, rcvd);

    // Trigger the NIC to send
    sendto(xsk_socket__fd(xsk->xsk), NULL, 0, MSG_DONTWAIT, NULL, 0);
}
```

