### 1. The XDP Program (`fast_forward.c`)
This program filters packets based on a target IP and forwards them (or drops them) in nanoseconds.

```c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

SEC("xdp_filter")
int xdp_prog_simple(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // Parse Ethernet header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) return XDP_PASS;

    // Only process IPv4
    if (eth->h_proto != __constant_htons(ETH_P_IP)) return XDP_PASS;

    // Parse IP header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) return XDP_PASS;

    // --- FILTERING LOGIC ---
    // Drop packets from a specific blacklisted IP (e.g., 192.168.1.100)
    if (iph->saddr == __constant_htonl(0xC0A80164)) {
        return XDP_DROP;
    }

    // --- FORWARDING/PASSING ---
    // XDP_PASS sends it to the standard kernel stack
    // To implement custom forwarding (e.g., to another port), 
    // you would use bpf_redirect_map()
    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
```

