int filter_and_forward(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    // Fast packet inspection
    struct ethhdr *eth = data;
    if (data + sizeof(struct ethhdr) > data_end) return XDP_DROP;

    // Drop malicious traffic before it ever hits the kernel
    if (is_denied(eth->h_source)) return XDP_DROP;

    // Pass to kernel or redirect to another interface
