}

// 2. The Packet Processing Loop
void process_packets(struct xsk_socket_info *xsk) {
    uint32_t idx_rx = 0;

    while (1) {
        // Poll the RX ring for new packets
        unsigned int rcvd = xsk_ring_cons__peek(&xsk->rx, 16, &idx_rx);

        for (int i = 0; i < rcvd; i++) {
            const struct xdp_desc *desc = xsk_ring_cons__rx_desc(&xsk->rx, idx_rx + i);
            char *pkt = xsk_umem__get_data(xsk->umem_area, desc->addr);

