#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);

    // 2. Create a memory pool for packets (mbufs)
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 
                                    MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. Configure the Ethernet device (simplified)
    uint16_t port = 0;
    rte_eth_dev_configure(port, 1, 1, &(struct rte_eth_conf){0});
    rte_eth_rx_queue_setup(port, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port), NULL, mbuf_pool);
    rte_eth_tx_queue_setup(port, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port), NULL);
    rte_eth_dev_start(port);

    // 4. Main Forwarding Loop
    struct rte_mbuf *bufs[32];
    while (1) {
        const uint16_t nb_rx = rte_eth_rx_burst(port, 0, bufs, 32);
        for (int i = 0; i < nb_rx; i++) {
            // PACKET FILTERING: Inspect Ethernet Header
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(bufs[i], struct rte_ether_hdr *);

            // Example Filter: Only forward if EtherType is IPv4
            if (eth_hdr->ether_type == rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4)) {
                // FORWARDING
                rte_eth_tx_burst(port, 0, &bufs[i], 1);
            } else {
                rte_pktmbuf_free(bufs[i]);
            }
        }
    }
    return 0;
}
```

### 3. Key Concepts for Low Latency
1.  **Poll Mode:** We use a `while(1)` loop (`rte_eth_rx_burst`). By constantly polling the hardware register, we avoid the latency overhead of kernel interrupts and context switching.
2.  **Zero Copy:** `bufs[i]` is a pointer to a physical memory address on the NIC's DMA ring buffer. We never copy the packet data; we only pass pointers around.
3.  **Hugepages:** DPDK uses "Hugepages" (1GB or 2MB chunks) for memory. This reduces TLB (Translation Lookaside Buffer) misses, which is a major source of latency jitter in standard applications.
4.  **CPU Isolation:** To get the best performance, use `isolcpus` in your Linux kernel boot parameters to dedicate specific CPU cores to the `while(1)` loop, preventing the OS scheduler from interrupting the service.

