    rte_eth_tx_queue_setup(0, 0, TX_RING_SIZE, rte_socket_id(), NULL);
    rte_eth_dev_start(0);

    struct rte_mbuf *bufs[32];

    // 4. Main Fast-Path Loop (The "Ultra-Low Latency" core)
    while (1) {
        // Poll for new packets
        uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, 32);

        for (uint16_t i = 0; i < nb_rx; i++) {
