    // Example: Only forward if it's an IPv4 packet
    return (rte_net_get_ptype(m) & RTE_PTYPE_L3_IPV4) != 0;
}

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "EAL init failed");

    // 2. Initialize Port (Simplified - assumes 1 port for brevity)
    uint16_t port = 0;
    struct rte_eth_conf port_conf = {0};
    rte_eth_dev_configure(port, 1, 1, &port_conf);
    rte_eth_rx_queue_setup(port, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port), NULL, NULL);
    rte_eth_tx_queue_setup(port, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port), NULL);
    rte_eth_dev_start(port);

    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 0, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. The "Fast Path" Polling Loop
    while (1) {
        struct rte_mbuf *bufs[32];
        const uint16_t nb_rx = rte_eth_rx_burst(port, 0, bufs, 32);

