```csharp
using System.Buffers;
using System.IO.Pipelines;
using System.Text;

public class FastStreamingParser
{
    public async Task ParseAsync(Stream inputStream)
    {
        var reader = PipeReader.Create(inputStream);

        while (true)
        {
            ReadResult result = await reader.ReadAsync();
            ReadOnlySequence<byte> buffer = result.Buffer;

            // Process segments of the buffer
            SequencePosition? consumed = ProcessSequence(ref buffer);

            reader.AdvanceTo(consumed ?? buffer.Start, buffer.End);

            if (result.IsCompleted) break;
        }
    }

    private SequencePosition? ProcessSequence(ref ReadOnlySequence<byte> buffer)
    {
        var reader = new SequenceReader<byte>(buffer);
        SequencePosition? lastPosition = null;

        // Example: Parsing a simple CSV-like format (e.g., "key,value\n")
        while (reader.TryReadTo(out ReadOnlySequence<byte> line, (byte)'\n'))
        {
            ProcessLine(line);
            lastPosition = reader.Position;
        }

        return lastPosition;
    }

    private void ProcessLine(ReadOnlySequence<byte> line)
    {
        // Zero-copy field extraction
        var lineReader = new SequenceReader<byte>(line);
        if (lineReader.TryReadTo(out ReadOnlySequence<byte> key, (byte)','))
        {
            // Use Span/ReadOnlySequence directly to avoid string allocation
            // Only convert to string if strictly necessary for business logic
            ReadOnlySpan<byte> keySpan = key.IsSingleSegment ? key.First.Span : key.ToArray();

            // Business logic goes here
            // e.g., Hash the key, update a counter, etc.
        }
    }
}
```

### Why this architecture is high-performance:

1.  **Memory Efficiency**:
    *   **No intermediate buffers**: `SequenceReader` operates directly on the memory buffers allocated by the `Pipe`.
    *   **Garbage Collection Friendly**: By using `ReadOnlySequence<byte>` and `Span<byte>`, you avoid creating thousands of small `string` objects that trigger GC pauses.
2.  **Throughput**:
    *   **Asynchronous I/O**: The `PipeReader` hides the complexity of async socket/file polling.
