	SourceLog     = "/var/log/app.log"
	BackupLog     = "/var/log/app.log.1"
)

func rotateLog(src, dst string) error {
	// 1. Open source
	s, err := os.OpenFile(src, os.O_RDWR, 0644)
	if err != nil {
		return err
	}
	defer s.Close()

	// 2. Create destination
