use std::io::{self, Read, Write};
use std::path::Path;

const BUFFER_SIZE: usize = 64 * 1024; // 64KB constant memory overhead

fn rotate_logs(source_path: &str, dest_path: &str) -> io::Result<()> {
    let mut source = OpenOptions::new()
        .read(true)
        .write(true)
        .open(source_path)?;

    let mut dest = OpenOptions::new()
        .create(true)
        .append(true)
        .open(dest_path)?;

