        if n == 0 { break; } // EOF
        dest.write_all(&buffer[..n])?;
    }

    // Ensure data is on disk before truncating
    dest.sync_all()?;

    // Truncate the source file to zero length (reclaims space)
    source.set_len(0)?;

    Ok(())
}

