#include <unistd.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_PATH 256
#define MAX_LOG_SIZE (10 * 1024 * 1024) // 10MB limit

/**
 * Rotates a single log file:
 * file.log -> file.log.1
 */
void rotate_log(const char *path) {
    char old_path[MAX_PATH];
    char new_path[MAX_PATH];

    snprintf(old_path, MAX_PATH, "%s", path);
    snprintf(new_path, MAX_PATH, "%s.1", path);

    // Atomic move
    if (rename(old_path, new_path) != 0) {
        return; // File might not exist
    }

    // Recreate the empty file
    int fd = open(old_path, O_CREAT | O_WRONLY, 0644);
    if (fd != -1) close(fd);
}

void check_and_rotate(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (st.st_size >= MAX_LOG_SIZE) {
            rotate_log(path);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;

    // Optional: Drop privileges here if running as root
    // setuid(1000); 

    while (1) {
        // We only track the specific file provided
        // No large data structures allocated on the heap
        check_and_rotate(argv[1]);

        // Sleep to save CPU cycles
        sleep(60); 
    }
    return 0;
}
```

