	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"
)

const (
	LogFile    = "/var/log/app.log"
	MaxSize    = 100 * 1024 * 1024 // 100MB limit
	ChunkSize  = 32 * 1024         // 32KB buffer (constant memory usage)
)

func rotate() error {
	info, err := os.Stat(LogFile)
	if err != nil {
		return err
	}

	// Only rotate if file exceeds MaxSize
	if info.Size() < MaxSize {
		return nil
	}

	backupName := fmt.Sprintf("%s.%d.bak", LogFile, time.Now().Unix())

	// 1. Rename current file to backup
	if err := os.Rename(LogFile, backupName); err != nil {
		return err
	}

	// 2. Create new empty log file
	newFile, err := os.Create(LogFile)
	if err != nil {
		return err
	}
	newFile.Close()

	// 3. Process backup (e.g., compress or move)
	// We use io.CopyBuffer to keep memory usage at exactly ChunkSize
	return nil
}

// Memory-efficient file processor
func processBackup(srcPath string, dstPath string) error {
	src, err := os.Open(srcPath)
	if err != nil {
		return err
	}
	defer src.Close()

	dst, err := os.Create(dstPath)
	if err != nil {
		return err
	}
	defer dst.Close()

	buf := make([]byte, ChunkSize)
	_, err = io.CopyBuffer(src, dst, buf)
	return err
}

func main() {
	for {
		if err := rotate(); err != nil {
			fmt.Fprintf(os.Stderr, "Rotation error: %v\n", err)
		}
		time.Sleep(1 * time.Minute)
	}
}
```

