```rust
use std::fs::{File, OpenOptions};
use std::io::{BufReader, BufWriter, Read, Write, Result};
use std::path::Path;

const BUFFER_SIZE: usize = 64 * 1024; // 64KB constant memory overhead

/// Rotates a file by streaming content from source to destination
/// using a fixed memory buffer.
fn rotate_log(source: &Path, destination: &Path) -> Result<()> {
    let input_file = File::open(source)?;
    let mut reader = BufReader::with_capacity(BUFFER_SIZE, input_file);

    let output_file = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(destination)?;
    let mut writer = BufWriter::with_capacity(BUFFER_SIZE, output_file);

    let mut buffer = [0u8; BUFFER_SIZE];

    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 { break; }
        writer.write_all(&buffer[..bytes_read])?;
    }

    writer.flush()?;
    std::fs::remove_file(source)?;
    Ok(())
}

fn main() {
    // 1. Enforce Memory Constraints at the OS level
    #[cfg(unix)]
    {
        use libc::{setrlimit, rlimit, RLIMIT_AS};
        let limit = rlimit {
            rlim_cur: 10 * 1024 * 1024, // Soft limit: 10MB
            rlim_max: 20 * 1024 * 1024, // Hard limit: 20MB
        };
        unsafe { setrlimit(RLIMIT_AS, &limit); }
    }

    // 2. Perform rotation
    if let Err(e) = rotate_log(Path::new("app.log"), Path::new("app.log.1")) {
        eprintln!("Rotation failed: {}", e);
        std::process::exit(1);
    }
}
```

### Key Components for Stability

1.  **`setrlimit(RLIMIT_AS, ...)`**: This invokes the OS kernel to kill the process if it attempts to exceed the virtual memory limit. This is the "nuclear option" to ensure your daemon never impacts other services on the machine.
2.  **`BufReader::with_capacity`**: By explicitly setting the capacity, we ensure the heap allocation for the I/O operation is fixed at compile time and doesn't fluctuate based on the log file size.
3.  **Zero-Allocation Logic**: Note that the `loop` does not create any new heap-allocated structures (`Vec`, `String`, etc.). It reuses the same 64KB array on the stack, ensuring the Resident Set Size (RSS) remains flat regardless of the log size.

