```javascript
const fs = require('fs');
const path = require('path');
const readline = require('readline');

class LogRotator {
    constructor(config) {
        this.logPath = config.path;
        this.maxSize = config.maxSize || 10 * 1024 * 1024; // 10MB default
        this.highWaterMark = 16 * 1024; // 16KB buffer size (strict memory control)
    }

    async rotate() {
        const stats = fs.statSync(this.logPath);
        if (stats.size < this.maxSize) return;

        const rotatedPath = `${this.logPath}.${Date.now()}.old`;

        // Step 1: Rename the current file (O(1) operation, memory-safe)
        fs.renameSync(this.logPath, rotatedPath);

        // Step 2: Touch a new file to resume logging
        fs.writeFileSync(this.logPath, '');

        // Step 3: Process the rotated file in a memory-efficient stream
        this.processRotatedFile(rotatedPath);
    }

    processRotatedFile(filePath) {
        const instream = fs.createReadStream(filePath, { 
            highWaterMark: this.highWaterMark 
        });

        const rl = readline.createInterface({
            input: instream,
            terminal: false
        });

        rl.on('line', (line) => {
            // Processing happens here line-by-line.
            // Garbage collector clears the 'line' string immediately after iteration.
            this.archiveLine(line);
        });

        rl.on('close', () => {
            console.log('Rotation processing complete.');
            fs.unlinkSync(filePath); // Cleanup after processing
        });
    }

    archiveLine(line) {
        // Logic to push to external storage/db
    }
}

// Usage
