use sysinfo::{CpuRefreshKind, RefreshKind, System};
use tokio::time::{self, Duration};
use std::process;

// Configuration
const INTERVAL_MS: u64 = 1000;

struct Monitor {
    sys: System,
}

impl Monitor {
    fn new() -> Self {
        Self {
            sys: System::new_with_specifics(
                RefreshKind::new()
                    .with_cpu(CpuRefreshKind::everything())
                    .with_memory(),
            ),
        }
    }

    fn tick(&mut self) {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();

        let cpu_usage: f32 = self.sys.global_cpu_info().cpu_usage();
        let mem_used = self.sys.used_memory();
        let mem_total = self.sys.total_memory();

        println!(
            "[{}] CPU: {:.1}% | RAM: {}/{} KB",
            chrono::Local::now().format("%H:%M:%S"),
            cpu_usage,
            mem_used,
            mem_total
        );

        // Logic for resource management (e.g., kill process if memory > 95%)
        if (mem_used as f64 / mem_total as f64) > 0.95 {
            eprintln!("CRITICAL: Memory threshold exceeded!");
            // Add custom remediation logic here
        }
    }
}

#[tokio::main]
async fn main() {
    println!("Daemon starting...");
    let mut monitor = Monitor::new();
    let mut interval = time::interval(Duration::from_millis(INTERVAL_MS));

    loop {
        interval.tick().await;
        monitor.tick();
    }
}
```

