```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <thread>
#include <chrono>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>

// Simple structure to hold CPU ticks
struct CpuStats {
    long long user, nice, system, idle, iowait, irq, softirq;
};

// Function to fetch CPU stats from /proc/stat
CpuStats get_cpu_stats() {
    std::ifstream file("/proc/stat");
    std::string line;
    std::getline(file, line); // Read the first line (cpu)

    CpuStats stats;
    sscanf(line.c_str(), "cpu %lld %lld %lld %lld %lld %lld %lld",
           &stats.user, &stats.nice, &stats.system, &stats.idle, 
           &stats.iowait, &stats.irq, &stats.softirq);
    return stats;
}

// Daemonization logic
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);
    if (setsid() < 0) exit(EXIT_FAILURE);

    // Redirect standard streams
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    openlog("sys_monitor_daemon", LOG_PID, LOG_DAEMON);
}

bool keep_running = true;
void signal_handler(int sig) { keep_running = false; }

int main() {
    daemonize();
    syslog(LOG_INFO, "Daemon started.");

    signal(SIGTERM, signal_handler);

    CpuStats prev = get_cpu_stats();

    while (keep_running) {
        std::this_thread::sleep_for(std::chrono::seconds(2));

        CpuStats curr = get_cpu_stats();

        // Calculate CPU usage percentage
        auto idle_delta = (curr.idle + curr.iowait) - (prev.idle + prev.iowait);
        auto total_delta = (curr.user + curr.nice + curr.system + curr.idle + curr.iowait + curr.irq + curr.softirq) -
                           (prev.user + prev.nice + prev.system + prev.idle + prev.iowait + prev.irq + prev.softirq);

        double usage = 100.0 * (1.0 - (double)idle_delta / total_delta);

        syslog(LOG_INFO, "CPU Usage: %.2f%%", usage);

        prev = curr;
    }

    syslog(LOG_INFO, "Daemon terminated.");
    closelog();
    return 0;
}
```

### Key High-Performance Features:

1.  **Direct `/proc` Parsing:** Instead of shelling out to command-line tools like `top` or `ps` (which are expensive because they spawn new processes), we read `/proc/stat` directly. This uses minimal CPU and memory.
2.  **Syslog Integration:** We use `syslog` for logging rather than writing to local files. Syslog is asynchronous and highly optimized for background services.
3.  **Minimal Locking:** The design uses a single-threaded loop. If you need to monitor hundreds of metrics, switch to `epoll` (Linux event notification) to monitor multiple file descriptors (like netlink sockets for network or cgroups for memory) simultaneously without busy-waiting.
4.  **Signal Handling:** Proper daemon shutdown handling ensures that the resource manager releases locks and closes file handles gracefully.

