#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unistd.h>
#include <sys/epoll.h>
#include <signal.h>
#include <sys/timerfd.h>

bool running = true;

// Signal handler to stop the daemon
void signal_handler(int sig) {
    running = false;
}

// Simple function to read CPU usage from /proc/stat
void report_cpu_usage() {
    std::ifstream file("/proc/stat");
    std::string line;
    std::getline(file, line);
    std::cout << "[Monitor] CPU Stats: " << line << std::endl;
}

int main() {
    // 1. Setup Signal Handling
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    // 2. Create a timer (triggers every 2 seconds)
    int timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    itimerspec ts;
    ts.it_interval.tv_sec = 2; // Repeat every 2s
    ts.it_interval.tv_nsec = 0;
    ts.it_value.tv_sec = 1;    // Start in 1s
    ts.it_value.tv_nsec = 0;
    timerfd_settime(timer_fd, 0, &ts, nullptr);

    // 3. Setup epoll
    int epoll_fd = epoll_create1(0);
    epoll_event event;
    event.events = EPOLLIN;
    event.data.fd = timer_fd;
    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, timer_fd, &event);

    std::cout << "Daemon started. Monitoring resources..." << std::endl;

    // 4. Main Event Loop
    epoll_event events[1];
    while (running) {
        int n = epoll_wait(epoll_fd, events, 1, -1);
        if (n > 0) {
            uint64_t exp;
            read(timer_fd, &exp, sizeof(uint64_t)); // Clear timer
            report_cpu_usage();
        }
    }

    close(timer_fd);
    close(epoll_fd);
    std::cout << "Daemon shutting down." << std::endl;
    return 0;
}
```

