#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <string.h>

static int running = 1;

// Signal handler to allow clean shutdown
void handle_signal(int sig) {
    running = 0;
}

void daemonize() {
    pid_t pid = fork();

    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS); // Terminate parent
    if (setsid() < 0) exit(EXIT_FAILURE); // Become session leader

    // Fork again to ensure we don't re-acquire a terminal
    pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    umask(0);
    chdir("/");

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

int main() {
    daemonize();

    openlog("sys_monitor", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, "Daemon started successfully.");

    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    while (running) {
        // High-performance logic goes here
        // Example: Parsing /proc/stat to get CPU usage
        syslog(LOG_DEBUG, "Monitoring system resources...");

        sleep(5); // Adjust frequency based on performance requirements
    }

    syslog(LOG_INFO, "Daemon shutting down.");
    closelog();
    return 0;
}
```

