use sysinfo::{CpuRefreshKind, RefreshKind, System};
use tokio::time::{self, Duration};
use tracing::{info, Level};

struct Monitor {
    sys: System,
}

impl Monitor {
    fn new() -> Self {
        Self {
            // Initialize with only the data we actually need for performance
            sys: System::new_with_specifics(
                RefreshKind::new()
                    .with_cpu(CpuRefreshKind::everything())
                    .with_memory(),
            ),
        }
    }

    async fn run(&mut self, interval_ms: u64) {
        let mut interval = time::interval(Duration::from_millis(interval_ms));

        loop {
            interval.tick().await;

            // Update only the metrics we need
            self.sys.refresh_cpu();
            self.sys.refresh_memory();

            let cpu_usage: f32 = self.sys.global_cpu_info().cpu_usage();
            let mem_used = self.sys.used_memory();
            let mem_total = self.sys.total_memory();

            info!(
                cpu_usage = %format!("{:.2}%", cpu_usage),
                mem_usage = %format!("{:.2}%", (mem_used as f32 / mem_total as f32) * 100.0),
                "System Snapshot"
            );
        }
    }
}

#[tokio::main]
async fn main() {
    // Initialize structured logging
    tracing_subscriber::fmt().with_max_level(Level::INFO).init();

    info!("Starting Resource Monitor Daemon...");

    let mut monitor = Monitor::new();

    // Monitor every 2 seconds
    monitor.run(2000).await;
}
```

