#include <unistd.h>
#include <sys/epoll.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>

#define MAX_EVENTS 10

// Function to daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);
    if (setsid() < 0) exit(EXIT_FAILURE);

    // Redirect standard I/O to /dev/null
    freopen("/dev/null", "r", stdin);
    freopen("/dev/null", "w", stdout);
    freopen("/dev/null", "w", stderr);
}

int main() {
    daemonize();
    openlog("sys-monitor", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, "System Monitor Daemon Started.");

    int epoll_fd = epoll_create1(0);
    struct epoll_event event, events[MAX_EVENTS];

    // Example: Monitor a system resource file (e.g., CPU load)
    int fd = open("/proc/loadavg", O_RDONLY | O_NONBLOCK);
    event.events = EPOLLIN | EPOLLET; 
    event.data.fd = fd;
    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, fd, &event);

    while (1) {
        int n = epoll_wait(epoll_fd, events, MAX_EVENTS, -1);
        for (int i = 0; i < n; i++) {
            syslog(LOG_INFO, "Resource change detected! Updating metrics...");
            // Reset file pointer for next read
            lseek(fd, 0, SEEK_SET); 
        }
    }

    closelog();
    return 0;
}
```

