#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>

void daemonize() {
    pid_t pid;

    // Fork off the parent process
    pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS); // Parent exits
    if (setsid() < 0) exit(EXIT_FAILURE); // Become session leader

    // Ignore signal and fork again
    signal(SIGCHLD, SIG_IGN);
    signal(SIGHUP, SIG_IGN);

    pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    umask(0);
    chdir("/");

    // Close standard file descriptors
    for (int x = sysconf(_SC_OPEN_MAX); x >= 0; x--) {
        close(x);
    }
}

int main() {
    daemonize();
    openlog("resourcemon", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, "Resource Monitor started.");

    while (1) {
        // High-performance monitoring logic goes here
        // e.g., reading /proc/stat or /proc/meminfo
        syslog(LOG_INFO, "Monitoring resources...");
        sleep(5); 
    }

    closelog();
    return EXIT_SUCCESS;
}
```

