#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <thread>
#include <chrono>
#include <unistd.h>
#include <sys/stat.h>

class ResourceMonitor {
public:
    struct Stats {
        double cpu_usage;
        long mem_total;
        long mem_free;
    };

    // Non-blocking read of /proc/meminfo
    Stats collect() {
        Stats s;
        std::ifstream meminfo("/proc/meminfo");
        std::string label;
        long value;

        while (meminfo >> label >> value) {
            if (label == "MemTotal:") s.mem_total = value;
