    openlog("ResMonitor", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, "Daemon started.");

    signal(SIGTERM, handle_signal);

    while (keep_running) {
        // High-performance monitoring logic goes here
        // Example: reading /proc/stat
        syslog(LOG_DEBUG, "Monitoring system resources...");

        sleep(5); // Adjust frequency based on performance requirements
    }

    syslog(LOG_INFO, "Daemon shutting down.");
    closelog();
    return 0;
}
