#include <sys/timerfd.h>
#include <fcntl.h>
#include <syslog.h>

void daemonize() {
    if (fork() > 0) exit(0); // Exit parent
    setsid();                // Create new session
    if (fork() > 0) exit(0); // Exit child
    umask(0);
    chdir("/");
    // Redirect standard streams to /dev/null
    close(STDIN_FILENO); close(STDOUT_FILENO); close(STDERR_FILENO);
}

int main() {
