To create a high-performance system daemon in Linux, **C** or **Rust** are the standard choices. Below is a minimal, production-grade template written in **C**.

This implementation handles the two most important aspects of a daemon:
1. **Double-forking** (to detach from the terminal).
2. **Signal handling** (to shut down gracefully).

### `daemon.c`

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>

static int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void run_daemon() {
    // 1. Fork off the parent process
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS); // Terminate parent

    // 2. Create a new session
    if (setsid() < 0) exit(EXIT_FAILURE);

    // 3. Fork again to ensure we aren't a session leader
    pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    // 4. Set file permissions and change working directory
    umask(0);
    chdir("/");

    // 5. Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    openlog("my_monitor", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, "Daemon started.");

    // Main loop
    while (keep_running) {
        // --- High-Performance Logic Here ---
        // Example: Reading /proc/stat for CPU usage
        syslog(LOG_INFO, "Monitoring resources...");

        sleep(5); // Adjust frequency based on needs
    }

    syslog(LOG_INFO, "Daemon terminated.");
    closelog();
}

int main() {
    signal(SIGTERM, handle_signal);
    run_daemon();
    return 0;
}
```

