// Define buffer sizes for high-speed ring
#define NUM_FRAMES 4096
#define FRAME_SIZE 2048

struct xsk_socket_info {
    struct xsk_ring_cons rx;
    struct xsk_ring_prod fill;
    struct xsk_umem *umem;
    struct xsk_socket *xsk;
    void *buffer;
};

void process_packets(struct xsk_socket_info *xsk_info) {
    uint32_t idx_rx = 0;
    unsigned int rcvd;

    // Busy-poll loop
    while (1) {
        rcvd = xsk_ring_cons__peek(&xsk_info->rx, 32, &idx_rx);
        if (rcvd == 0) continue; // Keep polling

        for (int i = 0; i < rcvd; i++) {
            uint64_t addr = *xsk_ring_cons__rx_desc(&xsk_info->rx, idx_rx + i);
            uint8_t *pkt = xsk_umem__get_data(xsk_info->buffer, addr);

            // PERFORMANCE CRITICAL: Inline your analysis logic here
            // Avoid branch-heavy code. Use SIMD intrinsics for parsing headers.
            analyze_packet(pkt); 
        }

        xsk_ring_cons__release(&xsk_info->rx, rcvd);
        // Inform the kernel that we've consumed the buffers
        xsk_ring_prod__submit(&xsk_info->fill, rcvd);
    }
}
```

### Critical Optimization Checklist

To sustain 1 Gbps (and scale to 10/40/100 Gbps), you must apply these architectural constraints:

#### 1. Hardware/NIC Affinity (NUMA)
