### 1. The eBPF Program (`flow.c`)
This program runs in the NIC driver, intercepting packets before the kernel stack touches them.

```c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

// Hash map to store packet counts per source IP
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 10240);
    __type(key, __u32);
    __type(value, __u64);
} ip_counts SEC(".maps");

SEC("xdp")
int count_packets(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // Minimal parsing: Ethernet -> IP
    struct ethhdr *eth = data;
    if (data + sizeof(struct ethhdr) > data_end) return XDP_PASS;
    if (eth->h_proto != bpf_htons(ETH_P_IP)) return XDP_PASS;

    struct iphdr *iph = data + sizeof(struct ethhdr);
    if ((void *)iph + sizeof(struct iphdr) > data_end) return XDP_PASS;

    // Update map counter
    __u32 src_ip = iph->saddr;
    __u64 *val = bpf_map_lookup_elem(&ip_counts, &src_ip);
    if (val) {
        __sync_fetch_and_add(val, 1);
    } else {
        __u64 init_val = 1;
        bpf_map_update_elem(&ip_counts, &src_ip, &init_val, BPF_ANY);
    }

    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
```

