#include <sys/socket.h>
#include <sys/mman.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#define RING_FRAMES 2048
#define FRAME_SIZE 4096

int main() {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));

    // 1. Setup RX_RING
    struct tpacket_req req = {
        .tp_block_size = FRAME_SIZE * 8,
        .tp_block_nr = RING_FRAMES / 8,
        .tp_frame_size = FRAME_SIZE,
        .tp_frame_nr = RING_FRAMES
    };
    setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req));

    // 2. Map Ring into memory
    uint8_t *ring = mmap(NULL, req.tp_block_size * req.tp_block_nr, 
                         PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);

    // 3. Busy-poll loop
    struct tpacket_hdr *header = (struct tpacket_hdr *)ring;
    while (1) {
        if (header->tp_status & TP_STATUS_USER) {
            // Process packet at header + header->tp_mac
            printf("Captured packet, size: %d\n", header->tp_len);

            // Return ownership to kernel
            header->tp_status = TP_STATUS_KERNEL;
            header = (void*)header + FRAME_SIZE;
            if ((void*)header >= (void*)(ring + (req.tp_block_size * req.tp_block_nr)))
                header = (struct tpacket_hdr *)ring;
        }
    }
    return 0;
