    __type(value, int);
} xsks_map SEC(".maps");

SEC("xdp")
int xdp_sock_prog(struct xdp_md *ctx) {
    int index = ctx->rx_queue_index;
    // Redirect packet to userspace XDP socket
    return bpf_redirect_map(&xsks_map, index, 0);
}

