### Scenario: Reading a Temperature Sensor (DHT22) and calculating a rolling average.

```cpp
#include <DHT.h> // Common library for temperature sensors

// Configuration
#define SENSOR_PIN 4
#define SENSOR_TYPE DHT22
#define SAMPLE_INTERVAL 2000 // Read every 2 seconds

DHT dht(SENSOR_PIN, SENSOR_TYPE);

// Variables for processing
unsigned long lastReadTime = 0;
float runningAverage = 0.0;
int sampleCount = 0;

void setup() {
  Serial.begin(115200);
  dht.begin();
  Serial.println("System Initialized.");
}

void loop() {
  unsigned long currentTime = millis();

  // Non-blocking timer: Check if it's time to read the sensor
  if (currentTime - lastReadTime >= SAMPLE_INTERVAL) {
    lastReadTime = currentTime;

    // 1. Read Data
    float temperature = dht.readTemperature();

    // 2. Validate Data
    if (isnan(temperature)) {
      Serial.println("Error: Failed to read from sensor!");
      return;
    }

    // 3. Process Data (Exponential Moving Average)
    processData(temperature);

    // 4. Output Results
    Serial.print("Current Temp: ");
    Serial.print(temperature);
    Serial.print(" | Moving Average: ");
    Serial.println(runningAverage);
  }
}

/**
 * Updates a moving average to smooth out sensor noise.
 * formula: new_avg = (alpha * new_value) + ((1 - alpha) * old_avg)
 */
void processData(float newValue) {
  float alpha = 0.2; // Smoothing factor (0.0 to 1.0)
  if (sampleCount == 0) {
    runningAverage = newValue;
  } else {
    runningAverage = (alpha * newValue) + ((1.0 - alpha) * runningAverage);
  }
  sampleCount++;
}
```

