### Firmware: Sensor Processor
This code reads a thermistor or potentiometer on `A0` and prints a smoothed result to the Serial monitor.

```cpp
/*
 * Microcontroller Firmware: Sensor Processing
 * Task: Read analog sensor, apply rolling average filter, output status.
 */

// Configuration
const int sensorPin = A0;      // Pin connected to sensor
const int numReadings = 10;    // Number of readings for smoothing
int readings[numReadings];     // Array to store readings
int readIndex = 0;             // Current index in array
long total = 0;                // Running total

void setup() {
  Serial.begin(9600);

  // Initialize readings array to 0
  for (int i = 0; i < numReadings; i++) {
    readings[i] = 0;
  }
}

void loop() {
  // 1. Process Sensor Data
  int average = getSmoothedSensorData();

  // 2. Business Logic (Example: Threshold check)
  if (average > 500) {
    // Perform action (e.g., turn on LED)
  }

  // 3. Output
  Serial.print("Filtered Value: ");
  Serial.println(average);

  delay(50); // Sample rate control
}

int getSmoothedSensorData() {
  // Subtract the last reading
  total = total - readings[readIndex];

  // Read from the sensor
  readings[readIndex] = analogRead(sensorPin);

  // Add reading to total
  total = total + readings[readIndex];

  // Advance to next position in array
  readIndex = readIndex + 1;

  // Wrap around to start of array
  if (readIndex >= numReadings) {
    readIndex = 0;
  }

  // Return the average
  return total / numReadings;
}
```

