This example demonstrates how to read a sensor (e.g., an Analog Temperature Sensor like the TMP36), perform a basic moving average filter to smooth the noise, and send the data over Serial.

### The Firmware Code (`main.c`)

```c
#include <Arduino.h>

// --- Configuration ---
#define SENSOR_PIN A0
#define SAMPLE_COUNT 10
#define READ_INTERVAL_MS 100

// --- Global Variables ---
float sensor_buffer[SAMPLE_COUNT];
int buffer_index = 0;

// --- Function Prototypes ---
float calculate_moving_average(float new_value);

void setup() {
    Serial.begin(9600);
    pinMode(SENSOR_PIN, INPUT);
}

void loop() {
    // 1. Read Raw Data
    int raw_adc = analogRead(SENSOR_PIN);

    // 2. Process Data (Convert ADC to Voltage)
    float voltage = (raw_adc * 5.0) / 1023.0;
    float temperature_c = (voltage - 0.5) * 100; // Formula for TMP36

    // 3. Apply Digital Filtering
    float smoothed_temp = calculate_moving_average(temperature_c);

    // 4. Output Data
    Serial.print("Raw: "); Serial.print(raw_adc);
    Serial.print(" | Smoothed Temp: "); Serial.println(smoothed_temp);

    delay(READ_INTERVAL_MS);
}

// Simple Moving Average Filter
float calculate_moving_average(float new_value) {
    sensor_buffer[buffer_index] = new_value;
    buffer_index = (buffer_index + 1) % SAMPLE_COUNT;

    float sum = 0;
    for(int i = 0; i < SAMPLE_COUNT; i++) {
        sum += sensor_buffer[i];
    }
    return sum / SAMPLE_COUNT;
}
```

