/*
 * Sensor Processing Firmware
 * Reads analog data, performs a moving average filter, 
 * and triggers an LED if the temperature exceeds a threshold.
 */

// --- Constants ---
const int SENSOR_PIN = A0;    // Pin connected to sensor
const int LED_PIN = 13;       // Built-in LED
const float THRESHOLD = 30.0; // Celsius threshold
const int SAMPLES = 10;       // Number of samples for smoothing

// --- Global Variables ---
float readings[SAMPLES];      // Buffer for moving average
int readIndex = 0;
float total = 0;

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);

  // Initialize buffer
  for (int i = 0; i < SAMPLES; i++) readings[i] = 0;
}

void loop() {
  // 1. Read Raw Data
  int rawValue = analogRead(SENSOR_PIN);

  // 2. Convert to Temperature (Example: 5V, 10-bit ADC, 10mV/degC)
  float voltage = rawValue * (5.0 / 1023.0);
  float temperatureC = voltage * 100.0;

  // 3. Process Data (Moving Average Filter to remove jitter)
  total = total - readings[readIndex];
  readings[readIndex] = temperatureC;
  total = total + readings[readIndex];
  readIndex = (readIndex + 1) % SAMPLES;
  float averageTemp = total / SAMPLES;

  // 4. Decision Logic
  if (averageTemp > THRESHOLD) {
    digitalWrite(LED_PIN, HIGH);
  } else {
    digitalWrite(LED_PIN, LOW);
  }

  // 5. Output for debugging
  Serial.print("Temp: ");
  Serial.print(averageTemp);
  Serial.println(" C");

  delay(100); // Sampling rate
}
```

