  // Convert to meaningful units (e.g., Voltage)
  return (avgRaw / 1023.0) * VOLTAGE_REF;
}

void setup() {
  Serial.begin(115200);
  pinMode(SENSOR_PIN, INPUT);
  Serial.println("System Initialized...");
}

void loop() {
  // 1. Data Acquisition
  float sensorValue = readFilteredSensor();

