  if (currentMillis - previousMillis >= SENSOR_INTERVAL) {
    previousMillis = currentMillis;

    // 1. Read Raw Data
    int rawValue = analogRead(SENSOR_PIN);

    // 2. Process Data (Apply Filter)
    smoothedValue = applyFilter((float)rawValue, smoothedValue);

    // 3. Logic/Decision Making
    if (smoothedValue > THRESHOLD) {
      Serial.print("ALERT: High value detected! -> ");
      Serial.println(smoothedValue);
    } else {
