  total -= readings[readIndex];       // Subtract the oldest reading
  readings[readIndex] = rawValue;     // Add the new reading
  total += readings[readIndex];       // Add the new reading to total
  readIndex++;                        // Advance to next position

  if (readIndex >= NUM_SAMPLES) {     // Wrap around at the end
    readIndex = 0;
  }

  return total / NUM_SAMPLES;         // Return the average
}

void loop() {
  static unsigned long lastMillis = 0;

  // Non-blocking timing
  if (millis() - lastMillis >= INTERVAL) {
    lastMillis = millis();

    // 1. Read Raw Data
    int rawValue = analogRead(SENSOR_PIN);

    // 2. Process Data
    float smoothedValue = getSmoothedValue(rawValue);

