### Firmware Structure

```cpp
#include <Arduino.h>

// --- Configuration ---
const int SENSOR_PIN = A0;
const int ALARM_PIN = 13;
const float THRESHOLD = 30.0; // Celsius
const float ALPHA = 0.1;      // Smoothing factor (0 < alpha <= 1)

// --- Global Variables ---
float filteredValue = 0.0;

// --- Helper Functions ---
float readTemperature() {
    int raw = analogRead(SENSOR_PIN);
    // Convert ADC value (0-1023) to voltage, then to temperature 
    // (Assuming TMP36 sensor: 10mV per degree, 500mV offset)
    float voltage = (raw / 1024.0) * 5.0;
    return (voltage - 0.5) * 100.0;
}

void setup() {
    pinMode(ALARM_PIN, OUTPUT);
    Serial.begin(9600);

    // Initialize filter with first reading
    filteredValue = readTemperature();
}

void loop() {
    // 1. SENSE
    float currentReading = readTemperature();

    // 2. PROCESS (Exponential Moving Average Filter)
    // Formula: y[n] = α * x[n] + (1 - α) * y[n-1]
    filteredValue = (ALPHA * currentReading) + ((1.0 - ALPHA) * filteredValue);

    // 3. ACT / LOGIC
    if (filteredValue > THRESHOLD) {
        digitalWrite(ALARM_PIN, HIGH);
    } else {
        digitalWrite(ALARM_PIN, LOW);
    }

    // 4. TELEMETRY
