    hardware_init();

    uint32_t last_sample_time = 0;
    uint32_t current_time = 0;

    while (1) {
        // Use a non-blocking timer (Simulated)
        if ((current_time - last_sample_time) >= SENSOR_INTERVAL) {

            // 1. Read
            uint16_t sensor_value = read_sensor(SENSOR_PIN);

            // 2. Process
            process_data(sensor_value);

            last_sample_time = current_time;
        }

        current_time++; // Incremented in real-time interrupt in production
        _delay_ms(1);   // Keeps loop consistent for this example
    }
}

void hardware_init(void) {
    // Set up ADC (Analog to Digital Converter)
    ADMUX = (1 << REFS0); // Use AVCC as reference
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1); // Enable ADC, Prescaler 64
}

uint16_t read_sensor(uint8_t pin) {
    ADMUX = (ADMUX & 0xF0) | (pin & 0x0F); // Select pin
    ADCSRA |= (1 << ADSC);                 // Start conversion
    while (ADCSRA & (1 << ADSC));          // Wait for conversion
    return ADC;
}

void process_data(uint16_t raw_value) {
    // Simple logic: If sensor value crosses threshold, trigger output
    if (raw_value > THRESHOLD) {
        // Turn on status LED (e.g., PORTB5)
        PORTB |= (1 << PORTB5);
    } else {
        PORTB &= ~(1 << PORTB5);
    }
}
