#include <stdbool.h>

// Configuration Constants
#define SENSOR_BUFFER_SIZE 8
#define THRESHOLD_VALUE    2048 // Example: trigger point at half-scale

// Simple Circular Buffer for Moving Average Filter
typedef struct {
    uint16_t buffer[SENSOR_BUFFER_SIZE];
    uint8_t index;
    uint32_t sum;
} SensorFilter;

// Function Prototypes
void System_Init(void);
uint16_t ADC_Read_Raw(void);
uint16_t Process_Sensor_Data(SensorFilter* filter, uint16_t new_sample);

int main(void) {
    System_Init();

    SensorFilter mySensor = {0};
    uint16_t smoothed_value = 0;

    while (1) {
        // 1. Read raw data
        uint16_t raw_data = ADC_Read_Raw();

        // 2. Process data (Filter/Smoothing)
        smoothed_value = Process_Sensor_Data(&mySensor, raw_data);

        // 3. Logic: Respond to processed data
        if (smoothed_value > THRESHOLD_VALUE) {
            // Trigger actuator or alert
        }

        // Small delay or sleep to save power
        // HAL_Delay(10); 
    }
}

/**
 * @brief Moving average filter to stabilize noisy sensor inputs.
 */
uint16_t Process_Sensor_Data(SensorFilter* f, uint16_t new_sample) {
    // Remove oldest value from sum
    f->sum -= f->buffer[f->index];

    // Add new value
    f->buffer[f->index] = new_sample;
    f->sum += new_sample;

    // Increment index and wrap around
    f->index = (f->index + 1) % SENSOR_BUFFER_SIZE;

    // Return average
    return (uint16_t)(f->sum / SENSOR_BUFFER_SIZE);
}

// Mock functions for hardware interface
void System_Init(void) { /* Initialize GPIO, ADC, Clocks here */ }
uint16_t ADC_Read_Raw(void) { return 1024; /* Simulated HW Read */ }
```

