    }
}

/**
 * @brief Timer Callback (Triggered every 10ms)
 */
void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim) {
    if (htim->Instance == TIM2) {
        HAL_ADC_Start(&hadc1);
        if (HAL_ADC_PollForConversion(&hadc1, 10) == HAL_OK) {
            raw_adc_value = HAL_ADC_GetValue(&hadc1);
            data_ready_flag = true;
        }
    }
}

/**
 * @brief Simple data processing (e.g., Moving Average or Voltage Conversion)
 */
void ProcessSensorData(uint16_t raw) {
    // Convert 12-bit ADC (0-4095) to Voltage (0-3.3V)
    processed_sensor_data = (raw * 3.3f) / 4095.0f;

    // Perform logic based on processed data
    if (processed_sensor_data > 2.5f) {
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET); // Trigger Alarm
    } else {
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_RESET);
    }
}
```

