float applyMovingAverage(float newValue);
void processData(float processedValue);

void setup() {
  Serial.begin(115200);
  pinMode(SENSOR_PIN, INPUT);

  // Initialize buffer
  for(int i = 0; i < NUM_SAMPLES; i++) sensorBuffer[i] = 0;

  Serial.println("System Initialized.");
}

void loop() {
  static unsigned long lastRun = 0;

  if (millis() - lastRun >= READ_INTERVAL) {
    // 1. Read
    float rawValue = readSensor();

    // 2. Process
    float cleanValue = applyMovingAverage(rawValue);

    // 3. Act
    processData(cleanValue);

    lastRun = millis();
  }
}

// Read raw ADC value and convert to physical units (e.g., Voltage)
