  sensorBuffer[bufferIndex] = newValue;
  bufferIndex = (bufferIndex + 1) % NUM_SAMPLES;

  float sum = 0;
  for(int i = 0; i < NUM_SAMPLES; i++) sum += sensorBuffer[i];
  return sum / NUM_SAMPLES;
}

// Decision logic
void processData(float processedValue) {
  Serial.print("Filtered Value: ");
  Serial.println(processedValue);

  if (processedValue > 2.5) {
    // Trigger alarm or control output
  }
}
