    ESP_LOGI(TAG, "Sensor task started");

    while (1) {
        // 1. Read
        float raw_value = read_sensor_hardware();

        // 2. Process
        float filtered_value = apply_filter(raw_value);

        // 3. Output/Action
        ESP_LOGI(TAG, "Raw: %.2f | Filtered: %.2f", raw_value, filtered_value);

        // 4. Delay to maintain sampling rate
        vTaskDelay(pdMS_TO_TICKS(SENSOR_READ_INTERVAL_MS));
    }
}

void app_main() {
    // Initialize peripherals here (e.g., i2c_param_config)

    // Create the processing task
    xTaskCreate(sensor_task, "sensor_task", 2048, NULL, 5, NULL);
}
