### 1. The Implementation (`main.c`)

```c
#include "main.h"

// Configuration constants
#define SENSOR_ADC_CHANNEL ADC_CHANNEL_0
#define FILTER_SIZE 8

// Global variables
ADC_HandleTypeDef hadc1;
UART_HandleTypeDef huart2;

// Function prototypes
void SystemClock_Config(void);
static void MX_ADC1_Init(void);
static void MX_USART2_UART_Init(void);

// Simple Moving Average Filter
uint32_t apply_filter(uint32_t new_sample) {
    static uint32_t buffer[FILTER_SIZE];
    static uint8_t index = 0;
    static uint32_t sum = 0;

    sum -= buffer[index];
    buffer[index] = new_sample;
    sum += buffer[index];

    index = (index + 1) % FILTER_SIZE;
    return (sum / FILTER_SIZE);
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_ADC1_Init();
    MX_USART2_UART_Init();

    uint32_t raw_adc_value = 0;
    char msg[50];

    while (1) {
        // 1. Trigger ADC conversion
        HAL_ADC_Start(&hadc1);
        if (HAL_ADC_PollForConversion(&hadc1, 10) == HAL_OK) {
            raw_adc_value = HAL_ADC_GetValue(&hadc1);
        }
        HAL_ADC_Stop(&hadc1);

        // 2. Process data (Filter)
        uint32_t filtered_value = apply_filter(raw_adc_value);

        // 3. Output via UART
        int len = sprintf(msg, "Sensor Val: %lu\r\n", filtered_value);
        HAL_UART_Transmit(&huart2, (uint8_t*)msg, len, 100);

        // 4. Sample rate control
        HAL_Delay(100); 
    }
}
```

