// Define the pin the sensor is connected to
const int sensorPin = A0;

// Variables for data processing
float filteredValue = 0;
const float alpha = 0.1; // Smoothing factor (0 < alpha < 1)

void setup() {
  // Initialize Serial for debugging
  Serial.begin(115200);
}

void loop() {
  // 1. READ: Get raw data from the sensor
  int rawValue = analogRead(sensorPin);

  // 2. PROCESS: Simple Exponential Moving Average (Low-pass filter)
  // Formula: Y(n) = α * X(n) + (1 - α) * Y(n-1)
  filteredValue = (alpha * rawValue) + ((1.0 - alpha) * filteredValue);

  // 3. OUTPUT: Send data to Serial monitor
  Serial.print("Raw: ");
  Serial.print(rawValue);
  Serial.print(" | Filtered: ");
  Serial.println(filteredValue);

  // Small delay for stability
  delay(10);
}
```

