// 1. Configuration
const int sensorPin = A0;    // Pin where sensor is connected
const int sampleCount = 10;  // For data processing
int readings[sampleCount];   // Buffer for moving average
int readIndex = 0;

void setup() {
  Serial.begin(9600); // Initialize communication for debugging
}

void loop() {
  // 2. Read Sensor Data
  int rawValue = analogRead(sensorPin);

  // 3. Process Data (Simple Moving Average Filter)
  readings[readIndex] = rawValue;
  readIndex = (readIndex + 1) % sampleCount;

  long sum = 0;
  for (int i = 0; i < sampleCount; i++) sum += readings[i];
  int processedValue = sum / sampleCount;

  // 4. Output Results
  Serial.print("Raw: ");
  Serial.print(rawValue);
  Serial.print(" | Filtered: ");
  Serial.println(processedValue);

  delay(50); // Small delay for stability
}
```

