#include <vector>
#include <cmath>

class AnomalyDetector {
private:
    int buffer_size;
    std::vector<float> buffer;
    int index = 0;
    float sum = 0.0f;
    float sq_sum = 0.0f;
    float threshold;

public:
    AnomalyDetector(int size, float sensitivity) 
        : buffer_size(size), threshold(sensitivity), buffer(size, 0.0f) {}

    bool process(float new_val) {
        // Remove old value from running statistics
        float old_val = buffer[index];
        sum -= old_val;
        sq_sum -= (old_val * old_val);

        // Add new value
        buffer[index] = new_val;
        sum += new_val;
        sq_sum += (new_val * new_val);

