```cpp
#include <vector>
#include <cmath>
#include <numeric>

#define WINDOW_SIZE 50    // Number of samples per window
#define THRESHOLD 3.0     // Z-score threshold for anomaly

class AnomalyDetector {
private:
    float buffer[WINDOW_SIZE];
    int index = 0;
    bool bufferFull = false;

    float getMean(float* data, int n) {
        float sum = 0;
        for(int i = 0; i < n; i++) sum += data[i];
        return sum / n;
    }

    float getStdDev(float* data, int n, float mean) {
        float sq_sum = 0;
        for(int i = 0; i < n; i++) sq_sum += pow(data[i] - mean, 2);
        return sqrt(sq_sum / n);
    }

public:
    // Processes a new sensor reading
    bool processSample(float sample) {
        buffer[index] = sample;
        index = (index + 1) % WINDOW_SIZE;
        if (index == 0) bufferFull = true;

        if (!bufferFull) return false; // Need enough data

        float mean = getMean(buffer, WINDOW_SIZE);
        float stdDev = getStdDev(buffer, WINDOW_SIZE, mean);

        // Avoid division by zero
        if (stdDev < 0.001) return false;

        // Calculate Z-Score
        float zScore = abs(sample - mean) / stdDev;

        // Return true if anomaly detected
        return (zScore > THRESHOLD);
    }
};

// --- Usage ---
AnomalyDetector detector;

void loop() {
    float accX = readAccelerometerX(); // Hardware abstraction

    if (detector.processSample(accX)) {
        triggerAlarm(); // Handle anomaly
    }
}
```

