```cpp
#include <math.h>

#define WINDOW_SIZE 20
#define THRESHOLD 3.0 // Z-Score threshold

class AnomalyDetector {
private:
    float buffer[WINDOW_SIZE];
    int index = 0;
    int count = 0;
    float sum = 0;

public:
    // Update the pipeline with a new 3-axis reading
    bool process(float x, float y, float z) {
        // 1. Feature Extraction: Calculate Magnitude
        float magnitude = sqrt(x*x + y*y + z*z);

        // 2. Statistical Analysis
        if (count == WINDOW_SIZE) {
            float mean = sum / WINDOW_SIZE;
            float stdDev = calculateStdDev(mean);

            // 3. Anomaly Detection (Z-Score)
            float zScore = abs(magnitude - mean) / (stdDev + 0.001); // +0.001 to avoid div by zero

            updateBuffer(magnitude);
            return (zScore > THRESHOLD);
        } else {
            updateBuffer(magnitude);
            return false;
        }
    }

private:
    void updateBuffer(float val) {
        sum -= buffer[index];
        buffer[index] = val;
        sum += buffer[index];
        index = (index + 1) % WINDOW_SIZE;
        if (count < WINDOW_SIZE) count++;
    }

    float calculateStdDev(float mean) {
        float sqSum = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            sqSum += pow(buffer[i] - mean, 2);
        }
        return sqrt(sqSum / WINDOW_SIZE);
    }
};

