#include <vector>
#include <cmath>
#include <numeric>

class AnomalyDetector {
private:
    float threshold;        // Sensitivity (e.g., 3.0 for 3-sigma)
    std::vector<float> buffer;
    size_t window_size;
    size_t index = 0;

public:
    AnomalyDetector(size_t size, float sigma_threshold) 
        : threshold(sigma_threshold), window_size(size) {
        buffer.resize(size, 0.0f);
    }

    bool process_sample(float sample) {
        // 1. Calculate Mean
        float sum = std::accumulate(buffer.begin(), buffer.end(), 0.0f);
        float mean = sum / window_size;

        // 2. Calculate Standard Deviation
        float sq_sum = 0.0f;
        for (float val : buffer) {
            sq_sum += (val - mean) * (val - mean);
        }
        float stdev = std::sqrt(sq_sum / window_size);

        // 3. Anomaly Logic (Z-Score)
        bool is_anomaly = false;
        if (stdev > 0.1f) { // Avoid division by zero/noise floor
            float z_score = std::abs(sample - mean) / stdev;
            if (z_score > threshold) {
                is_anomaly = true;
            }
        }

        // 4. Update Rolling Buffer
        buffer[index] = sample;
        index = (index + 1) % window_size;

        return is_anomaly;
    }
};
```

