#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define WINDOW_SIZE 50
#define THRESHOLD 3.0f // Number of standard deviations to trigger anomaly

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int is_full;
    float sum;
    float sq_sum;
} SensorStats;

// Add new sample and update running statistics (Welford's-like logic)
void update_stats(SensorStats *s, float new_val) {
    if (s->is_full) {
        float old_val = s->buffer[s->index];
        s->sum -= old_val;
        s->sq_sum -= (old_val * old_val);
    }

    s->buffer[s->index] = new_val;
    s->sum += new_val;
    s->sq_sum += (new_val * new_val);
    s->index = (s->index + 1) % WINDOW_SIZE;

    if (s->index == 0) s->is_full = 1;
}

// Detect if current value is an anomaly
int is_anomaly(SensorStats *s, float val) {
    int count = s->is_full ? WINDOW_SIZE : s->index;
    if (count < 10) return 0; // Warm-up period

    float mean = s->sum / count;
    float variance = (s->sq_sum / count) - (mean * mean);
    float std_dev = sqrtf(variance > 0 ? variance : 0);

    return (fabsf(val - mean) > (THRESHOLD * std_dev));
}

int main() {
    SensorStats accel_x = {0};

    // Simulated sensor stream
    float data[] = {1.0, 1.1, 1.0, 0.9, 1.0, 10.0, 1.0}; // 10.0 is anomaly

    for(int i = 0; i < 7; i++) {
