#include <cmath>
#include <numeric>

class AnomalyDetector {
private:
    std::vector<float> window;
    const size_t windowSize = 20;
    const float threshold = 3.0; // Sensitivity (3 sigma rule)

public:
    bool process(float newValue) {
        if (window.size() < windowSize) {
            window.push_back(newValue);
            return false;
        }

        // Calculate Mean
        float sum = std::accumulate(window.begin(), window.end(), 0.0);
        float mean = sum / windowSize;

        // Calculate Standard Deviation
        float sq_sum = 0;
        for(float x : window) sq_sum += (x - mean) * (x - mean);
        float stdev = std::sqrt(sq_sum / windowSize);

        // Detect Anomaly
        bool isAnomaly = std::abs(newValue - mean) > (threshold * stdev);

        // Update sliding window (remove oldest, add newest)
        window.erase(window.begin());
        window.push_back(newValue);

        return isAnomaly;
    }
};

