    int anomaly = (fabs(new_val - mean) > (THRESHOLD * std_dev));

    // Rolling update: remove oldest, add newest
    float old_val = stats->buffer[stats->index % WINDOW_SIZE];
    stats->sum = stats->sum - old_val + new_val;
    stats->sq_sum = stats->sq_sum - (old_val * old_val) + (new_val * new_val);
    stats->buffer[stats->index % WINDOW_SIZE] = new_val;
    stats->index++;

    return anomaly;
}

int main() {
