#include <stdbool.h>

#define FILTER_SIZE 8
#define THRESHOLD_ON 700
#define THRESHOLD_OFF 650

// Structure to keep state memory-efficient
typedef struct {
    uint16_t buffer[FILTER_SIZE];
    uint8_t index;
    uint32_t sum;
    bool actuator_state;
} EdgeController;

// Initialize state
void init_controller(EdgeController *c) {
    c->index = 0;
    c->sum = 0;
    c->actuator_state = false;
    for(int i=0; i<FILTER_SIZE; i++) c->buffer[i] = 0;
}

// Moving Average Filter (O(1) complexity)
uint16_t filter_sensor(EdgeController *c, uint16_t new_val) {
    c->sum -= c->buffer[c->index];
    c->buffer[c->index] = new_val;
    c->sum += new_val;
    c->index = (c->index + 1) % FILTER_SIZE;
    return (uint16_t)(c->sum / FILTER_SIZE);
}

// Logic to drive actuator
void update_actuator(EdgeController *c, uint16_t filtered_val) {
    if (filtered_val > THRESHOLD_ON) {
        c->actuator_state = true;  // Turn on
    } else if (filtered_val < THRESHOLD_OFF) {
        c->actuator_state = false; // Turn off
    }
    // Note: If val is between 650 and 700, state remains unchanged (Hysteresis)
}

// Main execution loop
void loop() {
    static EdgeController ctrl;
    static uint32_t last_run = 0;

    // Non-blocking task execution (e.g., run every 10ms)
    if (get_millis() - last_run > 10) {
        uint16_t raw_data = read_analog_sensor();
        uint16_t clean_data = filter_sensor(&ctrl, raw_data);

        update_actuator(&ctrl, clean_data);
        write_actuator(ctrl.actuator_state);

        last_run = get_millis();
    }
}
```

