    fs->sum -= fs->buffer[fs->index];
    fs->buffer[fs->index] = new_val;
    fs->sum += new_val;

    fs->index = (fs->index + 1) % BUFFER_SIZE;

    return fs->sum / BUFFER_SIZE;
}

