```cpp
#include <stdint.h>

// Configuration
#define SENSOR_PIN A0
#define ACTUATOR_PIN 9
#define THRESHOLD 500
#define WINDOW_SIZE 5

class EdgeNode {
private:
    uint16_t buffer[WINDOW_SIZE];
    uint8_t index = 0;

    // Simple Moving Average Filter
    uint16_t filter(uint16_t newValue) {
        buffer[index] = newValue;
        index = (index + 1) % WINDOW_SIZE;

        uint32_t sum = 0;
        for (uint8_t i = 0; i < WINDOW_SIZE; i++) sum += buffer[i];
        return (uint16_t)(sum / WINDOW_SIZE);
    }

public:
    void loop() {
        // 1. Acquire
        uint16_t rawValue = analogRead(SENSOR_PIN);

        // 2. Process (Filter)
        uint16_t filteredValue = filter(rawValue);

        // 3. Decide (Logic)
        if (filteredValue > THRESHOLD) {
            digitalWrite(ACTUATOR_PIN, HIGH); // Trigger Action
        } else {
            digitalWrite(ACTUATOR_PIN, LOW);
        }
    }
};

EdgeNode node;

void setup() {
    pinMode(ACTUATOR_PIN, OUTPUT);
}

void loop() {
    node.loop();
    delay(10); // Throttle frequency to save power
}
```

