const int ACTUATOR_PIN = 2;
const int BUFFER_SIZE = 10;
const float THRESHOLD = 70.0;

// Circular Buffer Class (Memory Efficient)
class MovingAverage {
private:
    float buffer[BUFFER_SIZE] = {0};
    int index = 0;
    float sum = 0;

public:
    float addAndGet(float newValue) {
        sum -= buffer[index];
        buffer[index] = newValue;
        sum += buffer[index];
        index = (index + 1) % BUFFER_SIZE;
        return sum / BUFFER_SIZE;
    }
};

MovingAverage filter;

