    // 3. Actuator Management (Hysteresis logic to prevent rapid switching)
    if (smoothedData > THRESHOLD) {
        digitalWrite(ACTUATOR_PIN, HIGH);
    } else {
        digitalWrite(ACTUATOR_PIN, LOW);
    }

    // 4. Debug output
