        varying vec2 vUv;
        void main() {
            float pulse = sin(vUv.x * 10.0 + time) * 0.5 + 0.5;
            gl_FragColor = vec4(0.0, pulse, 1.0, 1.0);
        }
    `
});

// 4. Create an Object
