    scene.add(sphere);
    camera.position.z = 3;

    // 4. Interaction & Animation
    window.addEventListener('mousemove', (e) => {
        pointLight.position.x = (e.clientX / window.innerWidth) * 4 - 2;
        pointLight.position.y = -(e.clientY / window.innerHeight) * 4 + 2;
    });

    function animate(time) {
        requestAnimationFrame(animate);
        sphere.rotation.y += 0.01;
        renderer.render(scene, camera);
    }
    animate();
</script>
</body>
</html>
```

### Key Components Explained:

1.  **`WebGLRenderer`**: This is the engine that talks to your GPU. `antialias: true` is enabled for smoother edges.
2.  **`ShaderMaterial`**: This is where the magic happens. 
