<!DOCTYPE html>
<html>
<head>
    <style>body { margin: 0; overflow: hidden; } canvas { display: block; }</style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://cdn.skypack.dev/three@0.136.0';

        // 1. Setup Scene
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // 2. Custom Shader (Toon Effect)
        const shaderMaterial = new THREE.ShaderMaterial({
            uniforms: {
                lightPos: { value: new THREE.Vector3(5, 5, 5) }
            },
            vertexShader: `
                varying vec3 vNormal;
                void main() {
                    vNormal = normalize(normalMatrix * normal);
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }
            `,
            fragmentShader: `
                varying vec3 vNormal;
                uniform vec3 lightPos;
                void main() {
                    float intensity = dot(vNormal, normalize(lightPos));
                    // Quantize colors for a "toon" look
                    if (intensity > 0.95) intensity = 1.0;
                    else if (intensity > 0.5) intensity = 0.7;
                    else intensity = 0.3;
                    gl_FragColor = vec4(0.2, 0.6, 1.0, 1.0) * intensity;
                }
            `
        });

        // 3. Create Object
        const geometry = new THREE.SphereGeometry(1, 64, 64);
        const sphere = new THREE.Mesh(geometry, shaderMaterial);
        scene.add(sphere);

        // 4. Dynamic Lighting
        const light = new THREE.PointLight(0xffffff, 1);
        scene.add(light);
        camera.position.z = 3;

        // 5. Animation Loop
        function animate(t) {
            requestAnimationFrame(animate);
            // Move light in a circle
            light.position.x = Math.sin(t * 0.002) * 3;
            light.position.z = Math.cos(t * 0.002) * 3;
            shaderMaterial.uniforms.lightPos.value = light.position;

            sphere.rotation.y += 0.01;
            renderer.render(scene, camera);
        }
        animate(0);
    </script>
</body>
</html>
```

### Key Components Explained:

1.  **Three.js Boilerplate**: We initialize the `Scene`, `Camera` (the observer), and `Renderer` (the engine that converts 3D math into pixels).
2.  **`ShaderMaterial`**: This is where the magic happens. 
    *   **Vertex Shader**: Runs on every corner (vertex) of the mesh. It passes the normal vectors to the fragment shader.
    *   **Fragment Shader**: Runs on every pixel. This is where we calculate light intensity using the `dot()` product between the surface normal and the light position.
3.  **Dynamic Update**: Inside the `animate()` function, we update the `lightPos` uniform. Because this happens every frame (60fps), the light appears to move smoothly around the sphere, and the custom shader recalculates the lighting in real-time.

