                vUv = uv;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `;

        const fragmentShader = `
            uniform float time;
            varying vec2 vUv;
            void main() {
                // Pulse effect based on time and UV coordinates
                float strength = sin(vUv.x * 10.0 + time) * 0.5 + 0.5;
                gl_FragColor = vec4(0.2, strength, 0.8, 1.0);
            }
        `;

        const geometry = new THREE.IcosahedronGeometry(1, 15);
        const material = new THREE.ShaderMaterial({
            uniforms: { time: { value: 0 } },
            vertexShader,
            fragmentShader,
            wireframe: false
        });

        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);

        // 3. Dynamic Lighting
        const light = new THREE.PointLight(0xffffff, 50, 100);
        scene.add(light);
        scene.add(new THREE.AmbientLight(0x404040));

        camera.position.z = 3;
        const controls = new OrbitControls(camera, renderer.domElement);

        // 4. Animation Loop
        function animate(t) {
            requestAnimationFrame(animate);

            // Move light in a circle
            light.position.x = Math.sin(t * 0.002) * 2;
            light.position.y = Math.cos(t * 0.002) * 2;

            // Update shader time uniform
            material.uniforms.time.value = t * 0.005;

            mesh.rotation.y += 0.01;
            controls.update();
            renderer.render(scene, camera);
        }

        animate(0);
    </script>
</body>
</html>
```

### Key Components Explained:

1.  **WebGLRenderer:** This is the engine that converts your 3D objects and shaders into pixel data on your screen.
2.  **`ShaderMaterial`:** This allows you to write GLSL code (the language GPUs speak). 
    *   **Vertex Shader:** Handles the positioning of vertices (the corners of your 3D model).
    *   **Fragment Shader:** Determines the color of every single pixel on your object. In this code, we used `sin(time)` to create a pulsing color effect.
3.  **OrbitControls:** This library handles the camera math, allowing you to click, drag, and zoom around your 3D object effortlessly.
4.  **`requestAnimationFrame`:** This creates a standard render loop (usually 60fps), updating the lighting position and shader uniforms every frame to maintain the "real-time" experience.

