                varying vec2 vUv;
                void main() {
                    // Create a moving plasma effect
                    vec2 p = vUv * 10.0;
                    float val = sin(p.x + uTime) + sin(p.y + uTime) + sin((p.x + p.y + uTime) * 0.5);
                    gl_FragColor = vec4(0.2, val * 0.5, 0.8, 1.0);
