        const pointLight = new THREE.PointLight(0xffffff, 1);
        scene.add(pointLight);
        scene.add(new THREE.AmbientLight(0x404040));

        camera.position.z = 3;

        // 4. Interaction: Dynamic light follows mouse
        window.addEventListener('mousemove', (e) => {
            pointLight.position.x = (e.clientX / window.innerWidth) * 2 - 1;
            pointLight.position.y = -(e.clientY / window.innerHeight) * 2 + 1;
        });

        // 5. Animation Loop
        function animate(t) {
            requestAnimationFrame(animate);
            uniforms.uTime.value = t * 0.002;
            mesh.rotation.y += 0.01;
            renderer.render(scene, camera);
        }
        animate();
