                varying vec2 vUv;
                void main() {
                    vUv = uv;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }
            `,
            fragmentShader: `
                uniform float time;
                varying vec2 vUv;
                void main() {
                    gl_FragColor = vec4(0.5 + 0.5 * sin(time + vUv.x * 10.0), 0.2, 0.8, 1.0);
