        function animate(time) {
            requestAnimationFrame(animate);
            shaderMat.uniforms.time.value = time * 0.002;
            mesh.rotation.y += 0.01;

            // Move light based on mouse
            light.position.set(Math.sin(time*0.001)*2, 1, Math.cos(time*0.001)*2);

