                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }
            `,
            fragmentShader: `
                uniform float time;
                varying vec2 vUv;
                void main() {
                    gl_FragColor = vec4(0.5 + 0.5*sin(vUv.x*10.0 + time), 0.5 + 0.5*cos(vUv.y*10.0 + time), 1.0, 1.0);
                }
            `
        });

        // 3. Dynamic Lighting
        const geometry = new THREE.SphereGeometry(1, 64, 64);
        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);

        const light = new THREE.PointLight(0xffffff, 2);
        scene.add(light);
        camera.position.z = 3;

        // 4. Interaction & Animation Loop
        window.addEventListener('mousemove', (e) => {
            light.position.x = (e.clientX / window.innerWidth) * 4 - 2;
            light.position.y = -(e.clientY / window.innerHeight) * 4 + 2;
        });

        function animate(t) {
            requestAnimationFrame(animate);
            uniforms.time.value = t * 0.002;
            mesh.rotation.y += 0.01;
            renderer.render(scene, camera);
        }
        animate();
    </script>
</body>
</html>
