Here, we use the engine's overlap query system to find physics bodies and apply a custom force to them.

```cpp
#include "CustomPhysicsComponent.h"
#include "Engine/World.h"
#include "Components/PrimitiveComponent.h"

void UCustomPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    TArray<FOverlapResult> Overlaps;
    FCollisionShape Shape = FCollisionShape::MakeSphere(Radius);

    // Check for physical bodies in range
    bool bHasOverlaps = GetWorld()->OverlapMultiByChannel(
        Overlaps, GetComponentLocation(), FQuat::Identity, 
        ECC_PhysicsBody, Shape
    );

    if (bHasOverlaps)
    {
        for (const FOverlapResult& Overlap : Overlaps)
        {
            UPrimitiveComponent* PrimComp = Overlap.GetComponent();
            if (PrimComp && PrimComp->IsSimulatingPhysics())
            {
                // Calculate direction (center of force to object)
                FVector Direction = (PrimComp->GetComponentLocation() - GetComponentLocation()).GetSafeNormal();

                // Apply Radial Impulse
                PrimComp->AddImpulse(Direction * ForceMagnitude * DeltaTime, NAME_None, true);
            }
        }
    }
}
```

