```csharp
public class CustomPhysicsBody : MonoBehaviour, ICustomPhysicsBody
{
    public Vector3 Velocity { get; set; }
    public float Mass = 1.0f;
    private Vector3 _forceAccumulator;

    public Vector3 Position 
    { 
        get => transform.position; 
        set => transform.position = value; 
    }

    public void ApplyForce(Vector3 force) => _forceAccumulator += force / Mass;

    public void Integrate(float dt)
    {
        // Euler Integration
        Velocity += _forceAccumulator * dt;
        Position += Velocity * dt;

        // Reset forces
        _forceAccumulator = Vector3.zero;

        // Apply damping
        Velocity *= 0.99f; 
    }
}
```

### 3. The Physics Engine (The "Manager")
This script manages the simulation step. By using `FixedUpdate`, we ensure the simulation is frame-rate independent.

```csharp
public class CustomPhysicsManager : MonoBehaviour
{
    [SerializeField] private Vector3 globalGravity = new Vector3(0, -9.81f, 0);
    private List<ICustomPhysicsBody> _bodies = new List<ICustomPhysicsBody>();

    public void RegisterBody(ICustomPhysicsBody body) => _bodies.Add(body);

    void FixedUpdate()
    {
        float dt = Time.fixedDeltaTime;

        foreach (var body in _bodies)
        {
            // Apply global forces
            body.ApplyForce(globalGravity * body.Mass);

            // Step the simulation
            body.Integrate(dt);
        }
    }
}
```

