// CustomPhysicsEngine.cpp
void UpdatePhysics(std::vector<PhysicsBody*>& bodies, float deltaTime) {
    const glm::vec3 gravity(0.0f, -9.81f, 0.0f);

    for (auto& body : bodies) {
        // F = ma -> a = F/m
        glm::vec3 acceleration = (body->forceAccumulator / body->mass) + gravity;

        // Velocity Verlet Integration
        body->velocity += acceleration * deltaTime;
        body->position += body->velocity * deltaTime;

        // Reset forces
        body->forceAccumulator = glm::vec3(0.0f);

        // Apply damping
        body->velocity *= (1.0f - body->drag * deltaTime);
    }
}
