    // 1. Calculate Acceleration (F = ma -> a = F/m)
    // Here we simulate gravity as a constant force
    FVector Acceleration = Gravity; 

    // 2. Integrate Velocity (v = v0 + at)
    Velocity += Acceleration * DeltaTime;

    // 3. Integrate Position (p = p0 + vt)
    FVector NewLocation = Owner->GetActorLocation() + (Velocity * DeltaTime);

    // 4. Update the Actor's transform
    Owner->SetActorLocation(NewLocation, true); // 'true' enables collision sweeping
