#### B. The Physics World (The Engine)
This acts as the system that processes all components during the engine's `Update()` loop.

```cpp
class PhysicsWorld {
    std::vector<PhysicsComponent*> bodies;

public:
    void Step(float deltaTime) {
        float gravity = -9.81f;

        for (auto* body : bodies) {
            if (body->isStatic) continue;

            // 1. Calculate Acceleration (F = ma -> a = F/m)
            Vector3 acceleration = body->force / body->mass;
            acceleration.y += gravity;

            // 2. Integrate Velocity (Semi-Implicit Euler)
            body->velocity += acceleration * deltaTime;

            // 3. Update Position (Assuming access to transform)
            // parentTransform->position += body->velocity * deltaTime;

            // 4. Reset Forces
            body->force = {0, 0, 0};
        }
    }
};
