#include <godot_cpp/classes/physics_body3d.hpp>

namespace godot {

class GravityWell : public Area3D {
    GDCLASS(GravityWell, Area3D)

private:
    float strength = 9.8;

protected:
    static void _bind_methods();

public:
    void _physics_process(double delta) override;
