### 3. The Implementation File (`MyPhysicsComponent.cpp`)
This logic manually applies a force to the parent actor's `UPrimitiveComponent` (the mesh) every frame.

```cpp
#include "MyPhysicsComponent.h"
#include "GameFramework/Actor.h"
#include "Components/PrimitiveComponent.h"

UMyPhysicsComponent::UMyPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    CustomGravityMultiplier = 1.0f;
}

void UMyPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, TickType);

    AActor* Owner = GetOwner();
    if (Owner)
    {
        // Find the root primitive component (the physics body)
        UPrimitiveComponent* RootPrim = Cast<UPrimitiveComponent>(Owner->GetRootComponent());

        if (RootPrim && RootPrim->IsSimulatingPhysics())
        {
            // Calculate force: Mass * Gravity * Multiplier
            FVector Gravity = FVector(0, 0, -980.f); 
            FVector ForceToApply = Gravity * RootPrim->GetMass() * CustomGravityMultiplier;

            // Apply constant force
            RootPrim->AddForce(ForceToApply, NAME_None, true);
        }
    }
}
```

