For financial systems, you must wrap operations in a transaction and ensure that if the external network call fails, the database state remains consistent.

```java
@Service
public class PaymentService {

    @Autowired
    private TransactionRepository repository;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // 1. Check idempotency
        Optional<PaymentTransaction> existing = repository.findByIdempotencyKey(request.getKey());
        if (existing.isPresent()) {
            return mapToResponse(existing.get());
        }

        // 2. Persist as PENDING
        PaymentTransaction tx = createInitialTransaction(request);
        repository.save(tx);

        try {
            // 3. Call External Gateway (e.g., SWIFT, ACH, Stripe API)
            PaymentGatewayResult result = externalGateway.execute(tx);

            // 4. Update status
            tx.setStatus(result.isSuccess() ? COMPLETED : FAILED);
            repository.save(tx);

            return mapToResponse(tx);
        } catch (Exception e) {
            tx.setStatus(FAILED);
            repository.save(tx);
            throw new PaymentProcessingException("Gateway timeout");
        }
    }
}
