### Core Implementation (Go)

```go
package payments

import (
	"context"
	"errors"
	"fmt"
	"github.com/google/uuid"
	"time"
)

// PaymentRequest represents the incoming instruction
type PaymentRequest struct {
	IdempotencyKey string
	SourceAccount  string
	TargetAccount  string
	Amount         float64
	Currency       string
}

// PaymentService handles the transaction lifecycle
type PaymentService struct {
	repo Repository // Interface for DB operations
}

func (s *PaymentService) ProcessPayment(ctx context.Context, req PaymentRequest) error {
	// 1. Idempotency Check: Have we processed this key before?
	exists, err := s.repo.CheckIdempotency(ctx, req.IdempotencyKey)
	if err != nil {
		return err
	}
	if exists {
		return fmt.Errorf("duplicate request: %s", req.IdempotencyKey)
	}

	// 2. ACID Transaction: Execute via Database
	return s.repo.ExecuteInTransaction(ctx, func(tx Transaction) error {
		// Verify balances
		balance, err := tx.GetBalance(req.SourceAccount)
		if err != nil || balance < req.Amount {
			return errors.New("insufficient funds")
		}

		// Debit Source
		if err := tx.UpdateBalance(req.SourceAccount, -req.Amount); err != nil {
			return err
		}

		// Credit Target
		if err := tx.UpdateBalance(req.TargetAccount, req.Amount); err != nil {
			return err
		}

		// Record Audit Log and Idempotency Key
		return tx.RecordTransaction(req)
	})
}
```

