@Service
public class PaymentService {

    private final AccountRepository accountRepo;
    private final TransactionRepository transactionRepo;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // 1. Check Idempotency (prevent duplicate processing)
        if (transactionRepo.existsByIdempotencyKey(request.idempotencyKey())) {
            return transactionRepo.findByKey(request.idempotencyKey()).toResponse();
        }

        // 2. Lock accounts to prevent race conditions (Pessimistic Locking)
        Account source = accountRepo.findByIdForUpdate(request.sourceAccountId());
        Account dest = accountRepo.findByIdForUpdate(request.destinationAccountId());

        // 3. Validation
        if (source.getBalance().compareTo(request.amount()) < 0) {
            throw new InsufficientFundsException("Insufficient funds in source account");
        }

        // 4. Perform Transfer
        source.debit(request.amount());
        dest.credit(request.amount());

        // 5. Persist
        accountRepo.save(source);
        accountRepo.save(dest);

        PaymentTransaction tx = transactionRepo.save(new PaymentTransaction(request, "SUCCESS"));

        return new PaymentResponse(tx.getId(), "SUCCESS");
    }
}
```

