	db    *sql.DB
	kafka KafkaProducer
}

func (s *PaymentService) ProcessPayment(ctx context.Context, req PaymentRequest) error {
	// 1. Start Database Transaction
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// 2. Check Idempotency (Prevent double processing)
	var existing PaymentStatus
	err = tx.QueryRow("SELECT status FROM payments WHERE idempotency_key = $1", req.IdempotencyKey).Scan(&existing)
