	"context"
	"database/sql"
	"errors"
	"fmt"
	"github.com/google/uuid"
)

type PaymentService struct {
	db *sql.DB
}

type PaymentRequest struct {
	IdempotencyKey string
	FromAccountID  string
	ToAccountID    string
	Amount         float64
	Currency       string
}

func (s *PaymentService) ProcessPayment(ctx context.Context, req PaymentRequest) error {
	// 1. Start Transaction
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// 2. Check Idempotency (prevent duplicate processing)
	var exists bool
	err = tx.QueryRow("SELECT EXISTS(SELECT 1 FROM processed_payments WHERE id = ?)", req.IdempotencyKey).Scan(&exists)
	if exists {
		return errors.New("payment already processed")
	}

	// 3. Perform Double-Entry update
	// Note: Accounts should be locked for update (SELECT ... FOR UPDATE) to prevent race conditions
	_, err = tx.ExecContext(ctx, "UPDATE accounts SET balance = balance - ? WHERE id = ? AND balance >= ?", req.Amount, req.FromAccountID, req.Amount)
	if err != nil {
		return fmt.Errorf("insufficient funds or account error: %w", err)
	}

	_, err = tx.ExecContext(ctx, "UPDATE accounts SET balance = balance + ? WHERE id = ?", req.Amount, req.ToAccountID)
	if err != nil {
		return err
	}

	// 4. Record the Audit Log/Transaction
	_, err = tx.ExecContext(ctx, "INSERT INTO processed_payments (id, from_acc, to_acc, amount) VALUES (?, ?, ?, ?)", 
		req.IdempotencyKey, req.FromAccountID, req.ToAccountID, req.Amount)
	if err != nil {
		return err
	}

	return tx.Commit()
}
```

