The critical requirement here is the **Idempotency Key**. If a network timeout occurs, the client can retry the request without fearing a double charge.

```typescript
import { v4 as uuidv4 } from 'uuid';

class PaymentService {
  private processedKeys = new Set<string>(); // Mock DB

  async processPayment(request: { idempotencyKey: string, amount: number, from: string, to: string }) {
    // 1. Idempotency Check
    if (this.processedKeys.has(request.idempotencyKey)) {
      return { status: 'ALREADY_PROCESSED', transactionId: ... };
    }

    // 2. Begin Atomic Transaction (Database ACID)
    try {
      await db.transaction(async (trx) => {
        // Validate sufficient funds
        const balance = await trx('accounts').where('id', request.from).select('balance');
        if (balance < request.amount) throw new Error('INSUFFICIENT_FUNDS');

        // Execute Ledger Update
        await trx('accounts').where('id', request.from).decrement('balance', request.amount);
        await trx('accounts').where('id', request.to).increment('balance', request.amount);

        // Log transaction
        await trx('ledger').insert({ ...request, status: 'COMPLETED' });
        this.processedKeys.add(request.idempotencyKey);
      });
    } catch (error) {
      return { status: 'FAILED', reason: error.message };
    }
  }
}
```

