// Define Transaction Status
enum PaymentStatus { PENDING = 'PENDING', COMPLETED = 'COMPLETED', FAILED = 'FAILED' }

interface PaymentRequest {
  idempotencyKey: string; // Crucial for distributed systems
  amount: number;
  currency: string;
  sourceAccountId: string;
  targetAccountId: string;
}

class PaymentProcessor {
  // Simulating a Database transaction
  async processPayment(req: PaymentRequest) {
    const session = await db.startTransaction();

    try {
      // 1. Check Idempotency (Has this request been processed before?)
      const existing = await db.transactions.find(req.idempotencyKey);
      if (existing) return existing;

      // 2. Debit Source Account (Atomic operation)
      await db.accounts.debit(req.sourceAccountId, req.amount, { session });

      // 3. Credit Target Account
      await db.accounts.credit(req.targetAccountId, req.amount, { session });

      // 4. Record Transaction
      const record = await db.transactions.create({
        ...req,
        status: PaymentStatus.COMPLETED,
        timestamp: new Date()
      }, { session });

      await session.commit();
      return record;
    } catch (error) {
      await session.abort();
      throw new Error("Payment Failed: " + error.message);
    }
  }
}
```

