```typescript
import Fastify from 'fastify';
import { z } from 'zod';
import { createContainer, asValue, asClass } from 'awilix';

// 1. Domain/Service Layer
class UserIntegrationService {
  async getExternalData(id: string) {
    // Simulate integration with corporate LDAP/Database
    return { id, status: 'ACTIVE', department: 'ENGINEERING' };
  }
}

// 2. Schema Validation (Strict Type Safety)
const UserSchema = z.object({
  id: z.string().uuid(),
});

// 3. DI Container Setup
const container = createContainer();
container.register({
  userService: asClass(UserIntegrationService).singleton(),
});

const app = Fastify({ logger: true });

// 4. API Route
app.get('/user/:id', async (request, reply) => {
  // Validate input
  const { id } = UserSchema.parse(request.params);

  // Resolve dependency
  const userService = container.resolve<UserIntegrationService>('userService');

  const data = await userService.getExternalData(id);
  return reply.send(data);
});

// 5. Global Error Handler (Corporate requirement: hide stack traces)
app.setErrorHandler((error, request, reply) => {
  if (error instanceof z.ZodError) {
    return reply.status(400).send({ error: 'Validation failed', details: error.errors });
  }
  request.log.error(error);
  reply.status(500).send({ error: 'Internal Corporate Service Error' });
});

app.listen({ port: 3000 });
```

