### 2. The Implementation (`server.cpp`)

```cpp
#include <iostream>
#include <vector>
#include <uv.h>

#define DEFAULT_PORT 8080
#define BACKLOG 128

void alloc_buffer(uv_handle_t* handle, size_t suggested_size, uv_buf_t* buf) {
    buf->base = new char[suggested_size];
    buf->len = suggested_size;
}

void on_write(uv_write_t* req, int status) {
    if (status) std::cerr << "Write error " << uv_strerror(status) << std::endl;
    delete[] (char*)req->data; // Clean up response buffer
    delete req;
}

void on_read(uv_stream_t* client, ssize_t nread, const uv_buf_t* buf) {
    if (nread > 0) {
        // Prepare response
        const char* response = "HTTP/1.1 200 OK\r\nContent-Length: 13\r\n\r\nHello World!\n";
        size_t len = strlen(response);
        char* res_buffer = new char[len];
        memcpy(res_buffer, response, len);

        uv_write_t* req = new uv_write_t;
        req->data = res_buffer;
        uv_buf_t wrbuf = uv_buf_init(res_buffer, len);

        uv_write(req, client, &wrbuf, 1, on_write);
    }

    if (nread < 0) {
        if (nread != UV_EOF) std::cerr << "Read error " << uv_err_name(nread) << std::endl;
        uv_close((uv_handle_t*)client, [](uv_handle_t* h) { delete (uv_tcp_t*)h; });
    }
    delete[] buf->base;
}

void on_new_connection(uv_stream_t* server, int status) {
    if (status < 0) return;

    uv_tcp_t* client = new uv_tcp_t;
    uv_tcp_init(server->loop, client);
    if (uv_accept(server, (uv_stream_t*)client) == 0) {
        uv_read_start((uv_stream_t*)client, alloc_buffer, on_read);
    } else {
        uv_close((uv_handle_t*)client, nullptr);
    }
}

int main() {
    uv_loop_t* loop = uv_default_loop();

    uv_tcp_t server;
    uv_tcp_init(loop, &server);

    struct sockaddr_in addr;
    uv_ip4_addr("0.0.0.0", DEFAULT_PORT, &addr);

    uv_tcp_bind(&server, (const struct sockaddr*)&addr, 0);
    int r = uv_listen((uv_stream_t*)&server, BACKLOG, on_new_connection);

    if (r) {
        std::cerr << "Listen error " << uv_strerror(r) << std::endl;
        return 1;
    }

    std::cout << "Server listening on port " << DEFAULT_PORT << "..." << std::endl;
    return uv_run(loop, UV_RUN_DEFAULT);
}
```

